window.GAME_DATA = {"version":"1.0.0","title":"还有一格电","chapters":[{"id":"c01","number":1,"title":"第一章　车票背面","firstSceneId":"c01-s01","sceneIds":["c01-s01","c01-s02","c01-s03","c01-s04","c01-s05"]},{"id":"c02","number":2,"title":"第二章　没有窗的房间","firstSceneId":"c02-s01","sceneIds":["c02-s01","c02-s02","c02-s03","c02-s04","c02-s05","c02-s06"]},{"id":"c03","number":3,"title":"第三章　先到店","firstSceneId":"c03-s01","sceneIds":["c03-s01","c03-s02","c03-s03","c03-s04","c03-s05"]},{"id":"c04","number":4,"title":"第四章　余额页","firstSceneId":"c04-s01","sceneIds":["c04-s01","c04-s02","c04-s03","c04-s04","c04-s05","c04-s06"]},{"id":"c05","number":5,"title":"第五章　电工手","firstSceneId":"c05-s01","sceneIds":["c05-s01","c05-s02","c05-s03","c05-s04"]},{"id":"c06","number":6,"title":"第六章　寄回去的钱","firstSceneId":"c06-s01","sceneIds":["c06-s01","c06-s02","c06-s03","c06-s04","c06-s05"]},{"id":"c07","number":7,"title":"第七章　旧车谈价","firstSceneId":"c07-s01","sceneIds":["c07-s01","c07-s02","c07-s03","c07-s04"]},{"id":"c08","number":8,"title":"第八章　走熟一条路","firstSceneId":"c08-s01","sceneIds":["c08-s01","c08-s02","c08-s03","c08-s04","c08-s05"]},{"id":"c09","number":9,"title":"第九章　雨天摔车","firstSceneId":"c09-s01","sceneIds":["c09-s01","c09-s02","c09-s03","c09-s04","c09-s05"]},{"id":"c10","number":10,"title":"第十章　全勤日历","firstSceneId":"c10-s01","sceneIds":["c10-s01","c10-s02","c10-s03","c10-s04","c10-s05","c10-s06"]},{"id":"c11","number":11,"title":"第十一章　四月三十日","firstSceneId":"c11-s01","sceneIds":["c11-s01","c11-s02","c11-s03","c11-s04","c11-s05"]},{"id":"c12","number":12,"title":"第十二章　门口的晚饭","firstSceneId":"c12-s01","sceneIds":["c12-s01","c12-s02","c12-s03","c12-s04","c12-s05","c12-s06"]},{"id":"c13","number":13,"title":"第十三章　电池掉格","firstSceneId":"c13-s01","sceneIds":["c13-s01","c13-s02","c13-s03","c13-s04"]},{"id":"c14","number":14,"title":"第十四章　把单号写下来","firstSceneId":"c14-s01","sceneIds":["c14-s01","c14-s02","c14-s03","c14-s04"]},{"id":"c15","number":15,"title":"第十五章　摔过的人先走","firstSceneId":"c15-s01","sceneIds":["c15-s01","c15-s02","c15-s03","c15-s04","c15-s05","c15-s06"]},{"id":"c16","number":16,"title":"第十六章　她买了回程票","firstSceneId":"c16-s01","sceneIds":["c16-s01","c16-s02","c16-s03","c16-s04","c16-s05"]},{"id":"c17","number":17,"title":"第十七章　窗口前","firstSceneId":"c17-s01","sceneIds":["c17-s01","c17-s02","c17-s03","c17-s04","c17-s05"]},{"id":"c18","number":18,"title":"第十八章　还有一格电","firstSceneId":"c18-s01","sceneIds":["c18-s01","c18-s02","c18-s03","c18-s04","c18-s05"]}],"scenes":[{"id":"c01-s01","chapterId":"c01","chapterNumber":1,"title":"抽屉里的四千元","location":"颍上修理铺","background":"shop","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["许翔把那张皱起边角的车票夹在身份证后面。家里人平常叫他翔子，车票背面用铅笔写着“北京站—北桥”，是他上车前记下的应聘地址。一路的手汗把字磨得发亮，纸边也软了。","出发前一晚，他在家乡的小修理铺把工具逐件擦过。桌上还有两只没取走的旧电扇，他给其中一只换了线。顾客来取时付了工钱，临走又问北京那边是不是一定能找到活。翔子说不知道，只把收到的钱记进当天账页，再放进抽屉；那四千块是几年里一点点攒下来的，不是关门时突然多出来的。","小铺的活儿有时挤在一两天，有时半天等不到一个人。他手上工具不少，却算不出下周能换回多少现钱。表哥转来一千时，他当面说清这是借款，等拿到工资就按月还；表哥没让他把小店工具都卖掉，只提醒他别把借来的钱当成路上可以随便花的数。"],"next":"c01-s02"},{"id":"c01-s02","chapterId":"c01","chapterNumber":1,"title":"路上的账","location":"进京列车","background":"night","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["四千块是翔子自己的存款，一千块是表哥借给他的路费和落脚钱。两笔加起来五千，他在手机计算器上算过三遍。车票和路上的吃喝已经花掉二百八，抵京时手头剩四千七百二十。他知道这个数不大，却仍以为，只要先找到活干，剩下的钱就能慢慢长回来。","车还没进站时，母亲打来电话。电话那边听得见小摊卷帘门刮过地面的声音，许福兰在旁边说了句什么，翔子没听清。母亲问他到了没有、晚上住哪儿、工作是不是已经谈妥。翔子说快到了，工作能不能做还得看一天；房间还没落实，明早先去看介绍来的地方。后半句他说得很快，像在替自己打断话头。母亲没有追问，只让他吃饭别省到胃上。","电话挂了，许福兰发来一张地铁站的照片，问北京的地铁是不是每一条都在地下。翔子回她：“有的在地上，找到了再告诉你。”车票背面的地址还在，他把手机收回去，等车门打开。"],"choice":{"flag":"c01_focus","prompt":"把哪件事先记进记录卡？","options":[{"value":"family","label":"家里的问候","note":"记录卡：母亲问住处和工作；许福兰想知道北京地铁的样子。"},{"value":"ledger","label":"起程账目","note":"记录卡：四千元存款加一千元借款；花掉二百八，抵京余四千七百二十。"}]},"next":"c01-s03"},{"id":"c01-s03","chapterId":"c01","chapterNumber":1,"title":"北桥站招人","location":"北京站至北桥站","background":"station","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["2018年四月的北京站外风很硬，风从广场那面钻过来，吹得翔子眼睛发涩。他把背包往肩上提了提，另一只手按着装维修工具的塑料袋。袋底的小扳手跟了他两年，柄上缠着一段黑胶布；工具不重，进城以后倒像身上唯一一件不需要解释的东西。介绍工作的人早在微信上发了地址，又补语音：“先去北桥站，找姓马的。他们缺人，车也能租。你有修车的手艺，电瓶车不难弄。”翔子没再问，怕多问一句就露出自己其实没准备好。","他坐地铁换了两次线，下车后跟着地图走。路牌上的字太多，楼也太高，导航箭头转了半圈才停住。底商玻璃门上写着“佑路配送服务”，门里两张折叠桌、一台饮水机，墙上贴着发黄的排班表。招人单上“多劳多得、上不封顶”几个红字很醒目，下面小字却写着具体收入按站点规则结算。","门里的人刚挂电话，手指还夹着一支没点着的烟。他抬眼问：“来应聘？”翔子说配送员，之前修过电动车。那人自称马力，是北桥站负责人，核对翔子的身份证姓名和号码，又抽出一张表让他填紧急联系人。马力问他以前送过没有，翔子说没有。马力说今天先跟着跑一单，让他知道订单、时间和门口是什么样。"],"next":"c01-s04"},{"id":"c01-s04","chapterId":"c01","chapterNumber":1,"title":"协议里的小字","location":"北桥站","background":"office","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["桌上放着《配送服务协议》。翔子慢慢读配送区域、结算周期、出勤要求和服务质量几项。有些词看不明白，他便把手指压在那一行上问：“这个调整，是不是迟到就扣？”马力把协议翻到后面，说要看订单记录和当月规定，不是看谁声音大；不懂的地方先圈出来。","佑路按协议在次月三日发上个月的结算，订单和时间留在觅单骑手端。站点管排班、出勤，餐馆等餐的情况各不一样。马力没有告诉他每月一定能挣多少，只说常见班次从早上十点半到晚上十点半，中间有空档，临时调班也会变。十二个小时，翔子在心里重复一遍，想起家乡修理铺下雨天从开门守到关门，真正换到手里的钱还不如一天工钱。他问每月能休几天，马力说排班表会写，通常要到二十五天上下；不出勤就没有对应的订单钱，奖励也按当月规定算。平台没单时不会按坐着的钟点算钱。翔子拍下排班表一角，照片不清楚，又站近些拍了一张。","翔子把服务质量调整圈在协议副本上，问有没有固定扣款上限。马力说没有统一数，对不上可以拿订单号回来核。翔子又问，自己的车是不是就能自己安排。马力回答，车是自己的能少一笔租金，可排班仍看站里，单子从平台来，这不是想跑就跑的工。翔子身上还剩下的钱要找房、吃饭、还表哥，最后仍签了名；不是他已信了协议，是不想让这一天只剩一张车票。"],"next":"c01-s05"},{"id":"c01-s05","chapterId":"c01","chapterNumber":1,"title":"第一单的西门","location":"北桥站与小区西门","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["马力把盖过章的协议副本递给翔子，又给他反光背心和装手机的防水袋。手机架是旧的，夹口松，他用自带的橡皮筋缠了一圈，晃过两下，屏幕才不再往下坠。鲁师傅把一辆蓝灰色电动车推来，检查车胎、刹车和车灯，在租赁单上写明押金与首月租费。翔子交了车押金五百、首月租金四百五，把收据夹进车票。","他跟着马力跑了两条街，觅单端短促地响了一声。餐馆不远，取餐窗口排着三个人；马力提醒他先看清订单号，别把两家的袋子拿反，话说完就接起另一个电话。翔子把车停在路边，抬头认店名，再低头核号码。纸袋很轻，汤盒却在里面滑了一下，他重新折好袋口、放进保温箱。地图蓝线拐过两个路口，最后停在围墙西侧一扇窄门前。保安告诉他送餐走北门，沿墙绕过去；订单时间没有停。他绕过两条窄巷，才看见灰色门楼，备注里没有门禁密码，电话响了几声才接通。","顾客先问他是不是还在西门。翔子说已经到北门，门卫刚让他绕过来，问三号楼从哪边进；顾客告诉他进门后右手第一排，家里老人刚睡着，别按门铃。翔子把楼号给门岗看，又重复一遍别按门铃。保安核对地址后抬手打开侧门，指给他右手第一排就是三号楼。翔子把餐放在顾客指定的门边，拍照、点完成。页面跳出超时记录，却暂时没有扣款数字，只提示月结时查看。回到车边，马力从站点群发来语音：“第一单都这样，别在门口站着发呆。路线不对就早点问。”翔子听完没有回。他看见那单进入待结算，旁边另有一格服务记录，便追上马力问是否现在就扣。马力说要等结算单出来，平台记录和公司结款不在同一页面，先留住订单号，不能替任何一边下结论。翔子用指甲刮了刮手机壳翘起的边；地图只多一段弯，没有记下门卫指的方向和那通电话。他重新数钱：五千减去路食二百八、车押金五百和首月租费四百五，手头还剩三千七百七十；房间、押金和头盔雨具都还没付。"],"next":"c02-s01"},{"id":"c02-s01","chapterId":"c02","chapterNumber":2,"title":"三楼尽头","location":"北京合租房","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["第二天上午，翔子跟着高姨从一楼走到三楼。楼道里有股潮湿的米味，二楼门边放着一盆葱，叶尖碰着栏杆。三楼尽头的屋没有窗，床头上方只有一块磨砂玻璃，白天也看不出外面是什么颜色。","屋里一张窄床、一只塑料柜和一把缺了靠背的椅子，床脚离墙不到一尺。翔子把背包横过来试了试，走道刚够一个人侧身。他站在门口，没问天黑以后是不是更闷；北京的房间不是他想要的样子，但他没多一笔钱慢慢挑。","高姨说九百一个月，押一付一，公共水电按人头摊，走廊和灶台自己收拾。翔子问住几天能退，她拿旧登记册给他看：押金按约退，水电另算，不跟房租混；每月十日前交下月房租，九号前都行，过了十号要先打电话说。她没有催他签，只把笔横在桌边。"],"next":"c02-s02"},{"id":"c02-s02","chapterId":"c02","chapterNumber":2,"title":"两笔押金","location":"无窗房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子把房租和押金先从脑子里的五千元里各减九百。加上车票和路上的饭二百八、车租押金与首月租费九百五，付完房间的第一笔钱后只剩一千九百七十。那九百房屋押金还在高姨手里，车子的五百押金还在鲁师傅那里：它们不是花掉的钱，却不能拿来吃饭。","再买头盔、雨衣、手机卡和保温袋，他预计要用四百二十；第一次结算前的饭、充电和零碎东西先划八百。等这些费用在四月陆续花完，真正能留到五月初的钱只剩七百五。押金另列一栏，不把可能退回来的钱算进消费，也不当作眼下的可用余额。","他没有再拿计算器按第二遍，数字已经排过队。他在租约上写身份证号码，高姨把收据撕给他。两个人没有继续谈北京房租贵不贵；她只提醒他，公共水池在走廊尽头，晚上十点以后别在那儿洗车，楼下住着老人。"],"next":"c02-s03"},{"id":"c02-s03","chapterId":"c02","chapterNumber":2,"title":"松动的插座","location":"无窗房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子先拉开塑料柜，柜门一角翘着。他用工具袋里的旧胶带绕了一圈，柜门才肯合拢。接着，他把充电器插进墙上的插座，插头一碰就掉下来。他蹲着托住面板试了两次，记下“找高姨看”，没有自己拆开。修车上的电路，不等于有权拆租住房里的线路。","他拔下插头，拍了面板照片发给高姨。高姨回他先别用，也别自己拆，等她找人检查。翔子把照片留在手机里，不再碰那把小螺丝刀；屋子是租来的，松动的插座也得由房东安排检查。"],"next":"c02-s04"},{"id":"c02-s04","chapterId":"c02","chapterNumber":2,"title":"等师傅检查","location":"无窗房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["高姨后来问翔子哪天在屋里。他说白天要出勤，收工时间也说不准。高姨说她会陪师傅上楼，不让他为检查插座专门等在房间。几天后，她带着修电师傅来查看，先确认断电，再拆下面板。","里头的夹口松了，插头一碰就往下滑。师傅处理好固定处，当场插拔几次翔子的充电器，插头不再掉，面板也没晃。翔子等师傅收起工具，才把充电器插上。指示灯亮了，他把自己的螺丝刀收回袋里；高姨说墙里的线路有问题先告诉她，他点点头，没有把会修车上的电路当成能擅动房屋线路的理由。"],"next":"c02-s05"},{"id":"c02-s05","chapterId":"c02","chapterNumber":2,"title":"头盔与保温袋","location":"街口用品店与北桥站","background":"shop","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子在墙上找了半天，才想起磨砂玻璃后面是楼道采光井，不是窗。把门打开，潮湿的米味和楼下炒菜的油烟一块涌进来；关上门，屋里只剩充电器指示灯。他把衣服叠进柜子，雨衣挂门后，工具袋塞到床底，身份证和两张押金收据压在枕边。","午后他去街口买装备。店老板把不同大小的保温袋摆开，告诉他哪只够装两份饭。翔子戴上头盔，系紧下巴带、用手晃过，才换小一号；雨衣袖口太宽，他把手套套在外面试，确认能盖住接缝。手机卡只选够接单导航的套餐，老板说流量快用完再续。","他把手机夹在车把上，屏幕边缘仍露在外面。防水袋能挡雨，却不能保温。店老板翻出几只旧方袋，翔子挑了底板没塌、拉链不顺的一只；老板挤了点润滑油，他在店里拉了几遍，确认能合上。头盔、雨衣、手机卡和保温袋一共四百二十元，收据没有混进房租账。"],"next":"c02-s06"},{"id":"c02-s06","chapterId":"c02","chapterNumber":2,"title":"路线记在纸上","location":"北桥站与合租房","background":"street","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["回到北桥站，门边正有人换电池。靠门坐着的何行远头发花白，拿抹布擦车把上的泥；旁边的宋嘉欣把两张订单纸叠在一起，在背面写时间。马力介绍他们后，宋嘉欣认出翔子是昨天从西门绕路的新骑手，语气里没有嘲笑。她说地图常把人带到门缝边，到了先看保安亭在哪侧。翔子想解释是地图先错了，话到嘴边又咽回去；手机里那条订单已经变灰，旁边有小小的超时标记。宋嘉欣问他记没记住门是什么样，他答西边一扇窄门，外面是两个路口。她说记“西门”，不记“门缝”，下一单地址变了，地图还是那张，门却可能不是同一扇。何师傅叠好抹布，手指关节粗，指甲边有黑油；他提醒先认清哪根线松了，累的时候别把小毛病当大故障。宋嘉欣把几家午餐店的大概出餐时间写在便签上，说这只是自己的记法，不准也不保证每天一样，路过可以再核；她又把翔子的第一单号圈起，说月底账有问题时，别只记得自己着急过。","几天后，同一小区的另一单又把翔子带到西边窄门。他没在原地试门，先问门岗北门怎么走，沿墙绕过去，从灰色门楼进到三号楼，页面没弹超时。顾客只说门口太绕，翔子点点头，没有告诉对方他上次已经绕过一遍。回站后宋嘉欣问他记下没有，他说记在脑子里；她看着他空着的手，说：“脑子不跟下一班交接。”他没顶嘴，在订单号旁写“西门不通，北门进，三号楼右手”。","四月剩下的日子被排班表分成一格一格。有时翔子跟宋嘉欣确认哪条巷子能通到小区后门，有时跟着何师傅看商户门口的取餐队伍；更多时候，他记下出发、到店和送达的时刻。这个月他上了二十个班，订单增加，钱却仍在待结算。一次晚班过十点回来，车后轮沾着干泥，他想去水池冲洗，又想起高姨说过夜里别洗车。楼道出口有人端碗经过，他把车挪开让路，只用干布蹭掉挡泥板和脚撑表面一层泥，仍留着干痕。房间没窗，雨衣挂在门后，开门进油烟潮气，关门屋里又没有风。门锁只隔开房间，隔不开楼道里的气味、脚步声和别人用水的时间。","四月最后一周，母亲问房间住得习不习惯。翔子只拍门锁给她看，没有拍那面磨砂玻璃，说先等月底结账。月底他把车票背面重新列账：路食二百八、车押金五百与首月四百五、房屋押金九百与首月房租九百、装备四百二，饭、充电和零碎约八百。七百五得撑到五月三日结算；两笔押金仍在别人手里，订单也仍在待结算。"],"next":"c03-s01"},{"id":"c03-s01","chapterId":"c03","chapterNumber":3,"title":"店门口的倒计时","location":"便当铺","background":"shop","portrait":"luojie","portraitLabel":"","speaker":"旁白","pages":["五月二日，太阳把便当铺门口晒出一道白线。翔子把车停在线外，先看订单，再看墙上的钟：顾客备注“开会前送到，麻烦快些”。店里只有骆姐一个人，蒸箱开着，刚出锅的菜往餐盒里装，窄桌上堆着十几个纸盒，封口胶带还没撕。她的手机支在调料瓶边，几行订单显示备餐中，其中两行已经点亮，餐盒却还没封口。骆姐擦了擦手，在商家端找到其中一单，拇指停在“出餐”附近又收回来；汤还没装，先按出餐，骑手到了也只能站着等。","窗外又停下一辆电动车，骑手头盔后沿贴着褪色荧光黄胶带。大家叫他胶带哥。他探头问二十七号好了没有，骆姐说先做他的，前面还有几个。翔子说自己的倒计时已经红了。骆姐没抬头，说她也不是按手机时间出菜，今天有人请假，她一个人做，没封好的饭不能递出去。"],"next":"c03-s02"},{"id":"c03-s02","chapterId":"c03","chapterNumber":3,"title":"电话里的会议","location":"便当铺门口","background":"shop","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子看见厨房还有半锅汤，案板边一叠没切完的葱。胶带哥也挂着另一单，问能不能先拿一份；骆姐摇头，封口和小票对不上，拿错了她赔不起。他把手机调暗，站到屋檐下，每隔一会儿往店里看。翔子没有劝他等，也没有叫他走；餐盒没封好谁也拿不走，屏幕的时间却不会暂停。","顾客打来电话问他到哪儿了。翔子说还在店里等餐，老板正在做，拿到就出发。顾客说一点有个会，楼下前台不能替她收，赶不上就得重新点一份。翔子答应先看能不能取上，挂断后进度条又少一格。他想起早上只吃了半个馒头，胃里空得发响。"],"next":"c03-s03"},{"id":"c03-s03","chapterId":"c03","chapterNumber":3,"title":"留下一条时间","location":"便当铺门口","background":"shop","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["翔子走到店门口给马力发消息，说餐还没出、订单时间在走。马力回他，符合站里这份协议的条件就上报商户延迟，别乱点；上报只是留记录，不保证平台改时间，离店前把取餐时间记下。翔子把到店时间抄在本子上，订单号写在旁边。他不知道这两行字能不能改变什么，只知道晚上容易把分钟记错。","他按下上报，红色时间照样往前走。再问骆姐餐什么时候好，骆姐说还差一个汤，要不先拿主食。翔子说汤漏了，顾客会认为没送全。骆姐只说：“那你就等等。”翔子在订单菜单里选商家出餐延迟，核对到店时间后确认。没有新的倒计时，只在页面角落多出一枚小图标。"],"next":"c03-s04"},{"id":"c03-s04","chapterId":"c03","chapterNumber":3,"title":"小票与门口","location":"便当铺至顾客楼下","background":"street","portrait":"luojie","portraitLabel":"","speaker":"旁白","pages":["骆姐把汤盖扣紧，问翔子刚才点了什么。他说报了出餐延迟，站里说符合条件就留记录。骆姐也在小票边上写下实际出餐时间，说自己得把实际情况留在纸上，省得最后谁都说不清。翔子问能不能拍照，她让他别把收银台拍进去。他只拍小票上的时间，才接过餐袋。","出了店门，预计时间已经变红。翔子把汤盒放平、拉好保温袋，往顾客地址去。路口新修围挡，导航让他多绕半条街；他找可通行的缺口，红灯停在白线后，没有从施工车后硬挤。手机路线估算没因施工更新，他没有再加速抢那点看不见的时间。"],"next":"c03-s05"},{"id":"c03-s05","chapterId":"c03","chapterNumber":3,"title":"送达不等于有解释","location":"办公楼入口与北桥站","background":"office","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["楼下前台不肯代收，指着“访客物品请自行取走”的牌子。订单备注写着不能代收，翔子没把袋子放上桌，退到入口外打电话。顾客说她马上下来，让他别放桌上。翔子把袋子放在脚边，手没离开提手，直到顾客夹着会议资料、胸牌还挂在脖子上急匆匆下来。她接过饭先说抱歉，又摸摸汤盒，说还热着，谢谢。","系统页面仍有迟到记录，商家延迟图标留在另一处，两者没有合并成解释。翔子把订单号、到店时间和取餐时间抄在车票背面。傍晚宋嘉欣看他的照片：小票上能看见骆姐写的出餐时间，却看不见商家端订单状态；截图有平台超时标记和延迟图标，两个画面没有合到一起。宋嘉欣没有替他下结论，只让他把订单号、到店、取餐、送达状态抄在同一页，照片按日期存。她不能说这张票能追回扣款，但至少以后知道问的是哪一单。"],"next":"c04-s01"},{"id":"c04-s01","chapterId":"c04","chapterNumber":4,"title":"四千九百到账","location":"无窗房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["五月三日早上，翔子醒得比闹铃早。屋里没窗，灯关着看不出天亮没有，他听走廊有人拎桶下楼。银行短信先跳出来：佑路配送转来四千九百元。他坐起来又躺回去，把那行字看了两遍，没有先把钱转给家里。钱不在觅单骑手端的待结算里，而是从公司账户进了银行卡；灰色订单列表和第一单的超时标记仍留在手机上。他翻出结算单，想先看看这笔数是怎么来的。","站点结算单列二十个出勤日、五百六十个完成订单。每单八元是四千四百八十，等级补贴一百六十八，阶段出勤奖励两百，高峰补助一百，服务调整负四十八；加起来正好四千九百。翔子沿着每一栏划过去，完成单数和补贴都能对上，最下面的调整却只有总数，没有订单号。"],"next":"c04-s02"},{"id":"c04-s02","chapterId":"c04","chapterNumber":4,"title":"不能替负数找名字","location":"北桥站办公室","background":"office","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["第一单的超时记录还在手机里。翔子把订单号抄到结算单空白处，却想不出负四十八是哪一单，还是几单合起来的。平台记录旁边没有金额，只写着“已记录”。他把纸带到北桥站，等马力抬头才问服务调整能不能看出对应订单。","马力说这是公司收到的结算明细，平台记录不是每一项都能往下拆；他能查站里能查的部分，不能编一个对应关系。翔子又问第一单超时算不算，马力指着没有订单号的结算单说，现在不能说就是它。翔子把疑问和号码留下，没有把四十八元直接记成第一单的扣款。"],"next":"c04-s03"},{"id":"c04-s03","chapterId":"c04","chapterNumber":4,"title":"交班纸上的黑伞","location":"北桥站门口","background":"station","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["宋嘉欣听见他们谈调整，问结算单有没有逐单对照。翔子把纸递给她，问第一单的超时会不会就是负四十八。她先看公司结算单，再看手机灰色记录，说单子没写订单号，现在不能把四十八块安到第一单上。她没有说这笔一定错，只问翔子上了几天班、哪几天没出勤。","宋嘉欣讲起以前做餐馆前台的一次交班：有人来找落下的黑伞，上一班只说送来一把。架子上两把伞都黑，伞柄也都缠着东西；她没有凭“应该是”递给客人，只问有没有记号，把“黑伞待认领，伞柄记号未核”写在交班纸上。接班的人知道不能随便交，客人留下联系方式，前台答应核清再回话。宋嘉欣后来只听说伞有人领了，不把结果写进自己经手的交班。","她说能保证的是把看见和做过的事情交清，没亲自确认的不能替下一班说已经处理。结算单也只说明翔子的班次、订单和调整，不能替他或整站作答。翔子把纸拿回来，知道暂时能做的是分开记录，而不是先把几个数字强行连起来。"],"choice":{"flag":"c04_focus","prompt":"记录卡先突出哪一项？","options":[{"value":"adjustment","label":"尚未对应的负数","note":"记录卡：服务调整负四十八没有订单号，不能归因到第一单。"},{"value":"handover","label":"待核的交接记录","note":"记录卡：宋嘉欣的黑伞交班只写已核与待核，不替下一班保证结果。"}]},"next":"c04-s04"},{"id":"c04-s04","chapterId":"c04","chapterNumber":4,"title":"不是实收的整月数","location":"北桥站","background":"office","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子想起门上的“上不封顶”，用手机计算器估一个没有缺勤的整月：二十八单一天，二十五天就是七百单；每单八元五千六，等级补贴二百一，出勤奖三百，高峰补助一百，再扣假设的服务调整两百，最后是六千零一十。","他把算式念给宋嘉欣听。她说这是按翔子站里的单价算的，不是招聘页上的数，也不是她的工资。翔子点点头，又从这项假设数里减去本月预算支出三千九百九十，计算器停在两千零二十。这只是按无缺勤假设数减预算后的余数，不入银行卡，也不是实际月末余额。"],"next":"c04-s05"},{"id":"c04-s05","chapterId":"c04","chapterNumber":4,"title":"按日期付款","location":"租住房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子把本月预算写在车票背面：房租九百，公共水电和通信两百，租车与充电五百四十，吃饭一千一，寄家里六百五，还表哥二百五，另留三百五给衣物、药和小修，合计三千九百九十。按真实到账四千九百减去预算，理论上剩九百一十；与首结算前的七百五相加，五月底约一千六百六十。","五月三日，他先给母亲转六百五，又给表哥还二百五；房租九百在十日前交，车租四百五在十五日前交。十日，高姨确认六月房租收到；十五日，鲁师傅撕下车租收据。车押金与房屋押金仍另列，没有跟消费混在一起；水电、饭钱、通信和零碎支出还会从余额里一笔笔扣。"],"next":"c04-s06"},{"id":"c04-s06","chapterId":"c04","chapterNumber":4,"title":"等学校通知","location":"租住房间","background":"room","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["翔子把六百五十的转账截图发给母亲。母亲问他是不是刚拿到钱，怎么这么快就往回寄；翔子说房租已付，剩下先按说好的数来。母亲说摊子这两天还算顺，没有催他多寄，也没说那点钱够不够，只嘱咐他月底前别把新雨衣弄丢。翔子知道家里并不是把每个缺口都塞到他手里，可家里能挪的地方有限，他能给的也有限。表哥收到二百五后问够不够吃饭，翔子把房租、车租和下次结算日写在本子上，回说暂时不用再借。表哥回“那就行”，没让他提前还清；翔子把一千元借款改成还剩七百五十。五月最后一天下午，他从站里回来，在手机上核对余额，账面可支用约一千六百六十；五月整月订单仍待结算，要到六月三日才知道实际到账。","随后，许福兰发来职校缴费通知，问报名和学费的日期。照片放大后仍有些字看不清，只读到秋季入学。翔子说等下个月结算到再答复，许福兰回了一个“好”，没有把这句话当成保证。通知上的金额和截止时间仍待核，翔子没有把它写成已经确定的支出。"],"next":"c05-s01"},{"id":"c05-s01","chapterId":"c05","chapterNumber":5,"title":"过减速带再看","location":"北桥站门口","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["六月三日的结算短信在午饭前到了，翔子的银行卡多了六千零一十元。他把数字写在“五月结算”下面，注明还未扣六月生活费。下午，何师傅的后车灯经过减速带就灭，平路骑几米又亮。翔子问还能不能骑，何师傅说能骑，但灯不亮就不跑夜单，把钥匙递给他，让他看看是线松还是灯坏，别弄出更多毛病。","翔子先确认电源开关，顺着后轮旁的线找。灯罩没裂，接头被车架震松；螺丝刀转过半圈还不稳，他拔开插头、擦去灰，再把线头压紧。何师傅问他以前修车收不收钱，又问自己算熟人还是客人。翔子抬头看见他没拿话逼人。","胶带哥在旁边问亮着就算修好吗。何师傅推车压过减速带，红光没灭，才从口袋里掏出十块和零钱说给他买水。翔子没有用新零件，便把钱推回去。何师傅说那算欠他一回，下次刹车不灵别自己扛；翔子说自己也不修刹车。后灯亮着，何师傅才并入车流。"],"next":"c05-s02"},{"id":"c05-s02","chapterId":"c05","chapterNumber":5,"title":"只查外部接点","location":"北桥站","background":"station","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["第二天下午，宋嘉欣推着车进站，说电池路上明明两格，过个坑就跳成一格，拔插后又回来。她把电池从卡槽取下，没有让翔子马上动手。翔子说先别拆，他只看外面的插头和卡扣，电池壳里面的问题要送修。宋嘉欣替他扶稳车把，还关掉接单页面，免得又跳来新单。","翔子看见外部插片边缘有浅黑磨痕，卡扣没断，接触面却松。两人让车轮压过站前裂缝，仪表格数忽然变了；重复两次，才确认问题在外部接触位置，没有拆开电池壳猜电芯。翔子到街口买小端子和绝缘套，花十二元，只替换卡槽外部能碰到的部分。","宋嘉欣自己把电池推回去，摇车、开灯、看仪表，再推到门口骑几米，回来又压过裂缝，电量仍停在两格。翔子只说先这样跑两天，还跳就别硬骑，拿去问鲁师傅。宋嘉欣问他耽误接单的时间要不要算；翔子说这次只用了几分钟，也不敢保证接触片能撑多久。宋嘉欣说她问的是他花出去的时间，不是零件能用几天；若不收工钱，就说清楚是他自己的决定，别等下次心里再算。翔子说人工不收，只照零件小票收十二元。宋嘉欣按小票数付，没有硬塞更多，也没把他的手艺说成不用算。"],"next":"c05-s03"},{"id":"c05-s03","chapterId":"c05","chapterNumber":5,"title":"两处待核的路线","location":"北桥站","background":"office","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["宋嘉欣说下次她帮翔子看路线，也不替他白干。她抽出手机壳里的便签，指着地图自动画出的一条后巷短线：白天见过有人推车进去，晚上开不开不知道；她只看见推车，没看见骑过去。翔子说自己也没走过，不要先写成捷径。","宋嘉欣在线旁写上“待核”，又问下次附近有正常订单时能否顺手看门岗和时段，不为核路专门绕行。翔子翻开路线页，指给她看餐馆旁一处入口：他只在午间走过，晚间还没核过。两人把两处都画上问号，在后巷旁标“见过推车，骑行待核”，约定遇到正常订单时分别留意，再把结果补回便签。马力提醒他别在站里摆摊，也别做不确定的活，真有人找修车要把时间和零件分开算，免得最后成了人情债。","何师傅两天后又骑过减速带，后灯没有闪，说这回算翔子帮他看一眼，不算欠一笔。宋嘉欣也重新压过站前裂缝，仪表没跳，才把日期和接触片写在便签上。她仍记着如果再断电就去鲁师傅那里测。"],"next":"c05-s04"},{"id":"c05-s04","chapterId":"c05","chapterNumber":5,"title":"手艺，别丢","location":"北桥站外","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子把两次现金进出记在账本边角：买小端子负十二，宋嘉欣补材料费正十二，人工零。何师傅那张买水的十块没有变成收入。数字落下去后，他觉得这行字比一笔陌生的结算好认：谁给的、为什么给，都能说清楚。","马力说修车手艺是好事，但别让一个小接头变成欠谁一整天工钱。翔子说自己没打算开摊。六月中旬，他在车票边缘添一行“手艺，别丢”，下面原来只有“买车：5700”。他没有划掉车价，只把修理铺目标写在旁边；车还要买，手也得继续练。修理铺仍是以后想做的事，不是已经开成的铺子。"],"next":"c06-s01"},{"id":"c06-s01","chapterId":"c06","chapterNumber":6,"title":"六月的缴费单","location":"北桥站与家乡摊位通话","background":"home","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["六月三日到账的五月结算仍在手机银行里。翔子先按计划给表哥转二百五，把欠款从七百五改成五百；十日前交九百房租，十五日前再交四百五车租。收据只有一个数，没有奖励或调整的小字。六月二十日，他在站里等订单时接到母亲电话，听见摊位塑料布被风掀起又按下去的声音。","母亲说许福兰职校的缴费单寄到家了，学费、住宿、书本费分成几栏，秋天开学前要交。她把通知摊在摊子上隔着电话念，几行日期挤在一起。翔子让她别急着折，再念一遍最晚交费日；风把摊边塑料布鼓起来，母亲把手机贴在肩上，一只手按住通知和秤盘，等风过去才重新拿起纸。翔子只听清“秋天”，没听清日期，便让她等许福兰拍清楚，再去学校问哪些费用必须先交，不把几栏不确定的数加成一个总额。"],"next":"c06-s02"},{"id":"c06-s02","chapterId":"c06","chapterNumber":6,"title":"先按说好的六百五","location":"北桥站门口","background":"station","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子把电动车支起来，脚尖顶住车轮。六月三日到账的钱已经分给房租、车租、吃饭、还款和家用；他告诉母亲，每个月先给六百五，按说好的来，多出来的要等下一次结算，六月做的活到七月三日才到账。","母亲说知道，让他先留房租和车租，别拿押金当钱。她没有追问一个月能挣多少，也没催他多寄，只问方便收款吗。翔子打开手机银行转六百五，母亲听见提示音说看到了，又提醒这是平常那一笔，报名费另算，不要因她提起学校就把余额掏空。"],"choice":{"flag":"c06_focus","prompt":"这通电话先记住哪条边界？","options":[{"value":"regular_transfer","label":"固定家用六百五","note":"记录卡：每月先按说好的转六百五，不能把押金当作可用钱。"},{"value":"school_pending","label":"学校费用待确认","note":"记录卡：报名费另算；住宿、书本与正式学费的时间和金额仍待学校通知。"}]},"next":"c06-s03"},{"id":"c06-s03","chapterId":"c06","chapterNumber":6,"title":"许福兰自己去问","location":"电话两端：北桥站与家乡","background":"home","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["许福兰接过电话，先问翔子北京的地铁是不是每站都能换线。翔子说有的站要走一段。她说自己看过学校公告，想学维修和电商，不想为了省学费去读不愿意的班。她看过翔子拆装车灯，知道手上有活不等于马上有钱，但至少能多一条找工作的路；学校开放日是她自己去的，不是母亲替她选了专业，电商课也是那时她觉得能学。","她问报名那笔能不能向学校打听分两次交，若可以就先填材料；不让翔子现在答应具体数。翔子原想说会想办法，最后只问她知道该问谁吗。许福兰说班主任电话写在通知上，明天去学校问。母亲提醒她把缴费单放好，翔子听出妹妹比自己更清楚那张纸上还有几道门。"],"next":"c06-s04"},{"id":"c06-s04","chapterId":"c06","chapterNumber":6,"title":"旧雨衣上的针脚","location":"街边餐馆与租住房间","background":"rain","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["电话挂断后，翔子接下一单。下午雨来得急，餐馆门口的雨棚只遮住取餐台，雨从侧边斜进来。他把手机装进防水袋，站到屋檐最里面等封口；雨衣腋下的旧缝已经松了，水沿手肘流进手套。订单没有因为雨停，他还是把客人的饭送完。回站后翻看袖口和腋下，衣服边缘也裂开了一点。","他想用下个月的钱买一套结实雨具，可六月结算还没到，七月到账的钱要先还车租、寄家和表哥分期；购物页的两套雨衣都贵到不能不看余额。他关掉页面，找出母亲以前塞进行李的针线包，里面有旧黑线和半根弯针。","翔子把雨衣翻到里侧，摸清裂口从哪针开始松，再把布边往里折，让新线穿进原来的针眼，避免在防水布上多扎一排洞。螺丝可以拧紧，布线却不能拉到底，否则布边起皱、针眼扩大。他借着不太亮的灯缝了两遍，在里侧打结。次日早上，他先让修过的一侧朝外，骑到街口买早点；水珠沿袖管滚下，没从腋下灌进去，但薄布遇久雨仍会湿。他记下“补雨衣，不买新”，没有把省下的钱先算成余额。"],"next":"c06-s05"},{"id":"c06-s05","chapterId":"c06","chapterNumber":6,"title":"没有写进通知的数","location":"学校、北桥站与租住房间","background":"home","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["许福兰把缴费通知从课本里抽出来，带到班主任桌前，先问眼下最早要办的是哪一项。老师沿着通知逐栏看，照纸面说明告诉她：先交报名费；住宿和书本费等后续通知，正式学费看入学安排。许福兰又指着住宿那栏问，自己是不是不该把它记成现在就要交。老师说按通知分开记，没写的先别补。她怕转述时把几栏写混，便按顺序念一遍；老师只指着原通知纠正她漏掉的栏目名，没有替学校解释尚未写出的安排。她把课程表背面的标记指给老师看，问会不会误读，老师又核了一遍，点头让她按原文留存。","许福兰把报名费圈出，旁边写“先”；住宿和书本费写“等通知”，正式学费写“看入学安排”。她把通知摊平，用课本压住卷起的纸角重新拍照，原件上的日期这回拍清楚了，却没有写明就是缴费截止日。聊天里先前那张模糊照片还在，她把新照片发过去，补一句别按旧照片去借钱，没通知的会再问。翔子回说只记待确认，不先转钱。那几栏仍不是已付学费，许福兰也没有用别人的说法替学校填日期。","晚上回站时，宋嘉欣把女儿发来的语音放给母亲听。孩子问暑假姥姥带她去公园时妈妈能不能回来，宋嘉欣没有马上答应，只说自己还在上班，等电话打完再说。她贴着手机和母亲商量：女儿放学后谁去接、周末能不能先住外婆家；若回乡找到固定班次，母亲愿不愿意接几天晚班。电话那头没有替她决定，只说还要看女儿课后安排。宋嘉欣把“回家”写在钱包夹层的小纸片上，拨给以前做过前台的一家小餐馆，问有没有固定班次、工资怎么发、晚班到几点。对方说眼下没有空缺，让她留个号码；她写下号码，没有因为一句“以后再说”就把回家那笔钱拿出来。","月底，翔子把六月的账逐项核完：六千零一十到账，常态开支三千九百九十，账户还剩三千六百八十。房租九百、公共开支一百二、车租四百五、充电耗材九十、饭钱一千一、通信八十、家用六百五、衣物零碎三百五、还表哥二百五都列在里面。房屋和车辆押金仍不能当余额；下一笔钱要等七月三日。许福兰的费用还在待确认，宋嘉欣也还没有拿到那份工作。"],"next":"c07-s01"},{"id":"c07-s01","chapterId":"c07","chapterNumber":7,"title":"铺子里的蓝灰车","location":"鲁师傅的小铺","background":"shop","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["7月31日，翔子把账本上的可用余额核到5990元。8月3日，7月的结算款才会到账；房租、车租、给家里的钱和表哥最后一期250元还没付。他把这些支出按日期列在纸边，没有把还没到银行卡里的钱算进去。车价仍是5700元，这个数没有因为他看过招聘单就变小，也没有因为多跑两天就自己消失。","七月末他问过鲁师傅，附近有没有手续清楚、还能骑几个月的旧车。鲁师傅让他等两天，说店后刚收来一辆，电池不算新，但车架和牌照材料都在。七月三十一日傍晚，翔子收工后把工具袋放进车篮，骑到鲁师傅的小铺。铺子挨着修手机和补鞋的摊位，门口几辆车的车把碰在一起。鲁师傅把一辆蓝灰色电动车从里面推出来，提醒他先别看漆，先看轮子、刹车和电池：钱是翔子自己掏，坏了以后也得由他自己用。","翔子捏了刹车，把前后轮各转一圈。挡泥板上有一道浅划痕，灯罩没裂，车线沿车架绑过一次，车座边缘磨白。他插上钥匙，拧动电门，车灯亮了，仪表电量格跳一下停在三格。他问续航能跑多少，鲁师傅说不报数字：车不是新车，平路、慢骑也许多跑一点，冬天和上坡另算；备用电池也是随车旧的。","翔子推车绕过两道减速带，再在铺门口刹住。刹车没有拖滞，车灯没灭，仪表仍是三格。他捏了捏轮胎，听了后轮轴承声，又取下电池看接口。眼前没测出明显毛病，不等于知道长途续航；短短一圈不能替他回答冬天能跑多远。行驶证上的编号与车架号逐位对上，牌照仍在鲁师傅名下，材料没有缺页。"],"choice":{"flag":"c07_check_focus","prompt":"把哪一项先记进检查卡？","options":[{"value":"battery","label":"电池状态","note":"记录：主电池与备用电池都旧，三格电不代表续航保证。"},{"value":"documents","label":"车辆材料","note":"记录：车架编号与行驶证对得上，牌照仍登记在鲁师傅名下。"}]},"next":"c07-s02"},{"id":"c07-s02","chapterId":"c07","chapterNumber":7,"title":"车价与手头余数","location":"鲁师傅的小铺","background":"shop","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["鲁师傅把条件说清：车价5700元，带旧备用电池和一次基础维修工时；以后换电池、接点等材料另算。他不把仪表上的三格说成续航保证。翔子问能不能等下次结算再说，鲁师傅把钥匙收回去：现在不交定金，他不能替人留车；两周后车若还在，就再看。钱是翔子自己的，不要为了让他少等几天先去借。","翔子回到站点，宋嘉欣问他看得怎么样。他说车还能骑，电池旧，价钱也不是假的，就是买完手里不宽。她问他现在有多少，翔子说5990；车价5700，租车押金能退500。照押金及时退回的情景算，买车后只剩790元。可这笔押金还在鲁师傅手里，不能在车交回前就当现金花。","如果赶在8月15日前交回租车，能免掉下一周期450元租金；但原来约90元的充电开支，要换成自有车电费和维修预留300元。表哥最后一期250元仍要还，购车情景下八月月支出约3750元。按最有利的押金及时退回计算，眼下790元仍比这笔支出少2960元。8月3日的结算款还没有进账，合同上的日期不能替银行卡提前生出钱。","翔子在旧纸上写下买完可用790、购车情景八月支出3750、未到账前短2960。若8月3日的6260元如期到账，付完这些支出后月底预计还剩3300元，但在工资到账、租车交回和押金退回之前，这只是一种预计。房屋押金900元仍在高姨手里，也不能补眼前的缺口。","翔子回到家后打开表哥的聊天框，打下车还差一点又停住。最后一期250元还没还，借来的钱不能被他当成不用回头的余额。他删掉那行，只发我按原约还，买车等到账再说。表哥回知道了，先把饭钱留够。翔子没有把这几句话记成新进账，只把手机放到算式旁。"],"next":"c07-s03"},{"id":"c07-s03","chapterId":"c07","chapterNumber":7,"title":"还没定下来的缴费单","location":"站点门口","background":"station","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["母亲在微信里发来一张缴费通知，说许福兰已经问过班主任，秋天报名之前要先准备一部分钱，首笔正式缴费预计在十月。翔子把照片放大，问最晚哪一天要交。母亲说学校还在等最后清单，能先准备的就先准备；尚未确定的数，不能拿别人的钱去填。","翔子又给许福兰发消息，问她是不是还想读、最早要交的那笔有没有问清。她说想读，班主任还在核对住宿和材料费，等通知确定就拍给他；她不想让哥哥因为一张模糊照片去借钱。翔子把十月圈在纸边，回她：我记着，但先别把我的回复当成保证。缴费日期和总数都还没定，这张通知不是已经付款的凭据。"],"next":"c07-s04"},{"id":"c07-s04","chapterId":"c07","chapterNumber":7,"title":"再试一次电池","location":"鲁师傅的小铺","background":"shop","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["第二天下班后，翔子又绕到鲁师傅店门口。车还在里面，前轮下面垫着一块木板。鲁师傅说备用电池已经充满，让他再试一遍。翔子把电池装上，绕铺子外面骑了一小圈；刚过第二个路口，仪表格就往下掉了一格。换回主电池，格数没有马上变化。","他没把短试当作续航保证，只把两块电池的差别记在心里。翔子又问登记材料和车型，和鲁师傅一起对车架编号、牌照与行驶证，再拍下资料回去核对北京目录。鲁师傅允许他拍照，却没有替他留车。谁也没说车一定会在，也没有哪句口头保证能变成电池检测结果。","回到站点后，翔子在账页中间重写5700元，下面留出车、家、没法预料的事三格。买车不是把车价转出去就算完；他还得有地方住、有饭吃，也要等下一笔结算真正到账。那辆蓝灰色车仍是一个没作出的决定，他没有交定金，也没有向表哥开口借钱。"],"next":"c08-s01"},{"id":"c08-s01","chapterId":"c08","chapterNumber":8,"title":"到账之后仍先算账","location":"站点","background":"station","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["8月3日，七月结算款到账6260元。上月底余额5990元，合在一起12250元。翔子没有立刻把车价转给鲁师傅，而是先把房租、车租、表哥最后一笔还款、寄家和生活费写下来；按这个顺序支出，月底预计剩8260元。","如果买车并赶在8月15日前交回租车，500元租车押金退回，5700元车款付出，当月能免掉下一周期450元租金；但充电90元要换成电费和维修预留300元，最后一期250元仍要还。购车情景月支出约3750元，月底预计剩3300，比购车后的普通月支出3500少200元，还没把旧备用电池风险和十月学校缴费放进去。","押金也不一定当天退。若退车前拿不到那500元，手头只会更紧。翔子把纸折起来塞到车票后面，没有把一张预计表当成现钱。他不是不想买，只是不想在一张尚未结清的订单页上，先替自己写下已经够了。"],"next":"c08-s02"},{"id":"c08-s02","chapterId":"c08","chapterNumber":8,"title":"两扇门之间","location":"住宅区入口","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["八月中旬一个午高峰，翔子接连收到两单，都送往同一片住宅区。第一家店给了一碗汤和一盒饭，第二家店的纸袋里装着几份凉菜。两张小票压在一起，他把汤盒放进保温袋最里侧、凉菜放在上面，再翻开两个地址。第一单导航指向西侧，第二单却从东门绕进去，两条蓝线像互不相认。","他没马上点导航。第一单剩余时间短一些，第二个地址在小区另一头；照蓝线走，得先从西门进去，再退出去绕到东门。翔子停在路边，摸出车票后的小本子：西门不通，北门进，三号楼右手；东门能走，但午间门岗要查楼号。","他把两张小票上的楼号又对一遍，给第一位顾客发消息，说自己从北门进，不会把饭放在门岗。到北门，保安问送几号楼。翔子报了楼号，保安认得那排住宅，让他先送三号楼，再沿内部连廊去另一头。第一单顾客正好在家，接过饭没让他多等。翔子拍照、点完成，回到门口再看第二单楼号，确认不是同一栋，才继续走。"],"next":"c08-s03"},{"id":"c08-s03","chapterId":"c08","chapterNumber":8,"title":"少绕的一段不等于收入","location":"住宅区连廊与站点","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["连廊边堆着住户搬下来的纸箱，推车从窄处经过，翔子收了收车把，让一位老人先走。保安看见保温袋，抬手给他指另一条小路。翔子记下那个转弯，却没把它写成地图上的捷径：有些路，只有人在门岗边站过才知道能不能走。","第二单送到时，顾客刚从楼里出来，手里还拿着钥匙。她说地图把她家标在东边。翔子说自己从北门进来，问以后备注能不能写清楚从哪边进。顾客看了眼屏幕，说一直以为地址点准就够了，随后在订单上点了完成。她没有抱怨迟到，他也没把绕行说成是她的错。","回到车边，胶带哥正站在门外看导航，问北门在哪。翔子指给他看围墙上的灰门和连廊方向，对方说声谢谢就骑进去。没有谁因为这几句提醒多拿一块钱。回站后，觅单停在等待派单，翔子把车支好，掰开半块饼坐在路边吃；空出来的几分钟没有自动变成下一单。他把少走的路记下来，也记下是否能接到新单并不是自己说了算。","收工后，他把新路线画给宋嘉欣看。她沿着图上的灰线划过去，问这条走廊晚上会不会锁。翔子只在白天走过，没试过晚班。宋嘉欣没有把路线写成捷径，只在旁边标了午间可走、晚间待问。"],"next":"c08-s04"},{"id":"c08-s04","chapterId":"c08","chapterNumber":8,"title":"门岗与排班表","location":"小区北门与北桥站","background":"office","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["几天后，翔子夜里又送进那片小区。北门的侧门已经锁了，他停在路灯下问门岗。保安让他改走东门、报楼号登记。翔子推车沿墙绕过去，到门岗时没有放下餐，也没先点送达；看见楼栋牌、把门牌逐字对上后，才继续上楼。手机预计时间已经发红。","他在本子上补了一行：夜间北门锁，东门要登记。第二天拿给宋嘉欣看，她把晚间待问划掉，补上东门先报楼号。胶带哥也在站里，核对完小区名，说自己白天从北门进、保安让他走连廊。翔子把这条加在午间可走旁边，几个人都在两本路线本上补了日期，没有把白天能走的门当成全天开放。","8月20日，马力把九月排班表贴在玻璃门后。翔子在表上找到自己的名字，数出一个休息日，又看手机里的觅单班次。两边都有日期，却不是一张表：站点表记他什么时候到岗，骑手端的范围决定他什么时候能接单。马力说，站点记出勤，平台决定当天派不派单；在线不代表公司记了班，出勤也不代表每一刻都有单。","翔子指着休息日问能不能换到前一天。马力说可以提前讲，他再看能不能调；不是把平台关掉，第二天再说自己今天想休，月底考勤报上去后就改不了。翔子把日期抄进本子，也把地图折回兜里。路线熟能减少一部分损耗，却不能替他决定什么时候上线，也不能让他从站点考勤里摘出去。"],"choice":{"flag":"c08_record_focus","prompt":"这次要先把哪项差异写进记录卡？","options":[{"value":"route_time","label":"按时段记入口","note":"记录：北门午间可走，夜间侧门会锁；东门需要报楼号登记。"},{"value":"shift_boundary","label":"区分两张排班表","note":"记录：站点管理出勤，平台决定接单范围；上线不等于公司记班。"}]},"next":"c08-s05"},{"id":"c08-s05","chapterId":"c08","chapterNumber":8,"title":"暂时系住的棚布","location":"老家摊位与站点","background":"home","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["八月下旬一晚，母亲把摊位棚布边绳松开的照片发来。风把布角吹起，旧绳头垂在支架外；翔子放大看，只能看清布边磨白，裂口有没有继续扩大却看不准。母亲的语音里有棚布拍打支架的声音，说许福兰拿家里剩下的绳头，想先把角系住。","许福兰说，第一次拉紧时布面起了褶，母亲叫她松一点。她拆开重系，把结绕过支架，留出一段余量，不让绳子勒着已经磨薄的地方。结好后，布角不再垂下来，边缘的白痕还在。她说出摊前会先检查；这只是眼下的临时处理，不等于棚布修好，冬天还得找人补。","母亲提醒她别把绳子扯成新的破口，许福兰说知道。翔子想替她们联系修理，话到嘴边又停住：隔着电话，他不知道摊架和布边怎么受力。母亲没有让他马上寄钱，只说冬天再找人看。他把照片留在手机里，没有替家里安排修法。","八月底，翔子把账重新核了一遍：八月到账6260元，日常开支3990元，手边剩8260元。他没有买车，也没有拿回租车押金；表哥最后一笔欠款已经还清，车租仍按月扣。即使把押金及时退回、再付车款，若过了15日成交，预付租车费不退，当月购车情景也只余3060元，比购车后的月均支出3500元少440元。车价旁边仍写着5700，路线本却多了几页。"],"next":"c09-s01"},{"id":"c09-s01","chapterId":"c09","chapterNumber":9,"title":"出勤奖励的字眼","location":"站点","background":"station","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["9月3日，八月结算到账6260元。翔子在站点看见手机银行多出一笔钱，先把租房、车租、家用和饭钱分开记，再把余额写进本子。等到10月3日，九月跑过的班次才会出现在银行卡上。","九月中旬，站里贴出下一轮出勤奖励说明。没有人说一定拿得到；马力只在群里提醒，想参加先看班次安排，缺勤会影响其中几项。翔子把纸拍下来，连同手机屏幕保护膜放进工具袋。他知道不该把奖励算进生活费，那个多出勤有机会的字眼却让他多接了两张晚单。"],"next":"c09-s02"},{"id":"c09-s02","chapterId":"c09","chapterNumber":9,"title":"雨里的窄路","location":"雨夜道路","background":"rain","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["连续出勤后的一个傍晚，翔子午饭只吃了半碗面，余下时间都在店门口和门岗之间来回跑。待结订单挤在手机上，下一单的送达时间比取餐时间还紧。他能把最后一份退回站里、改走大路；想到月底的出勤奖和还没买下来的车，他还是拧开车把，朝窄路骑去。","雨不大，却一直没停。头盔面罩挂着水珠，路灯照在柏油路上像薄油。翔子从小饭馆取了两份外卖，一份汤、一份盒饭。导航说绕大路会多走一段；主路口要等两个信号灯，小路平时能通车。他把汤盒往保温袋里侧推，告诉自己慢一点，应该赶得上下一轮派单。","转弯前，他看见地上的旧标线，却没有把车完全停下。雨水把白漆泡得发亮，他想从边缘压过去，前轮先滑，车身向左偏。他用手撑地，掌心擦过粗路面，右手腕被车把扭了一下。头盔侧面碰地擦出灰痕；他没撞到头，先抹掉脸上的雨水，再看保温袋。汤盒滚出几寸，盖子没开，电动车侧倒在浅水里，后灯和车架看不出明显损伤。","翔子坐在路边，先看订单，再看手掌。手机屏幕裂出一道斜线，触控还在；手腕发麻，能动，抬起来却疼。他没有马上站起来，等胸口那阵发紧过去才扶正车，拨给马力，说自己摔了、人在路口、车看着没坏。"],"next":"c09-s03"},{"id":"c09-s03","chapterId":"c09","chapterNumber":9,"title":"交接与三笔费用","location":"路边与社区门诊","background":"rain","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["马力问他能不能站、要不要叫救护车。翔子说能走，手腕疼但不晕。马力让他先别接单，发位置，站里找人来接车；订单按觅单页面处理，不能为了赶时间自己把餐送出去。胶带哥赶到后没有急着提袋子，先问还挂几单、每张小票尾号是什么。翔子把订单尾号、楼号、哪袋有汤逐项说清，胶带哥复述一遍，确认无误才接过保温袋。","平台页面把原单标成异常，没有立即显示扣款或赔偿。宋嘉欣赶到先看车轮和后灯，再看他的手，没有扳他的腕子，只问能不能握拳、有没有麻到手指。翔子试着动一动，她让他先去看医生，别拿还能动当没事；车由她看着，马力会来。","社区门诊做了简单检查，医生说是擦伤和轻度扭伤，先固定、冷敷，几天内别长时间骑；肿胀加重再复诊。检查和药费120元。医生没有开一张可以继续跑单的证明，也没说他几天后一定恢复。翔子把票据折好，收进钱包夹层。","第二天，他把租来的车推到鲁师傅那里检查车把、刹车、灯和电池。车没有摔坏，租赁协议也没有新增修理费。手机屏幕维修520元；腋下撕开的旧雨衣换成简易雨裤和外套，共220元。三笔支出合计860元，都是当月付掉，不等下次结算。手机裂屏后水汽沿裂纹渗进去，他只问维修店能否保留资料，没有问能不能赊账。"],"next":"c09-s04"},{"id":"c09-s04","chapterId":"c09","chapterNumber":9,"title":"五天空着的班次","location":"翔子的房间与站点","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["接下来的五天，翔子没有上线。第一天他用左手拧开水瓶，瓶盖滑了两次；第二天试着提工具袋，手腕刚一受力就缩回来。第三天他能用右手拿筷子，却提不稳桌上的水壶；第四天慢慢戴上头盔，手腕能转，急着扣带仍发涩。","他没把车推下楼测试，只看站点排班表的空格。觅单里九月订单记录停在摔倒那晚，家里发来的消息隔一会儿才回。第二个晚上母亲问医生怎么说，翔子把擦伤、扭伤和几天内不宜长时间骑行的建议一条条告诉她，没有只用没事搪塞。母亲问要不要来北京，他说不用，手边有药，宋嘉欣也帮忙看过车；她没问他什么时候能多寄钱，只叮嘱按医生说的休息、把票据留好。","宋嘉欣发来站里安排的交接时间，没有催他立刻回来，只问复诊时医生怎么说。翔子拍了药袋和检查票给她看。何师傅看过护腕，说他至少知道自己停了五天，别等疼到扶不住车才算。翔子没说我知道，只把护腕往上拉一点，露出掌心还没结实的擦伤。","第五天白天，他把租来的车推到院里，不开电门，只用右手握住车把，空捏几次刹把。头两下收得稳，第三下手腕开始发涩。他停住、甩甩手，没有把这几下当成能连续骑一班的证明。车推回墙边时，他决定复工第一天先走熟路。"],"next":"c09-s05"},{"id":"c09-s05","chapterId":"c09","chapterNumber":9,"title":"先走熟路","location":"复工路线与房间","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["第五天夜里，翔子打开排班群，发现下一周还能回原来的班次。他没有把满勤奖励算成必得，只在日历上标了复工日期。复工那天，他先捏刹车、试后灯，再把右手搭到车把上。腕子还紧但能握住；他重新缠好护腕，没有急着跑远单。","他沿熟悉的主路骑到第一个路口，停车等灯时松开手，活动两下，等发紧退一点再重新握回去。这只是一次短路，不足以证明能连续骑完一班。马力没问他是不是完全好了，只让他把能做的班次报清楚。翔子照常上线，接到订单先选自己熟悉的主路，没有因为空了五天立刻把单量补回来。","九月剩下的订单要等到10月3日结算。他现在只知道少跑了五个班，至于会少多少钱，还不知道。月底，他把手机修理单、门诊票和雨具价签压在同一页。车租照付，500元租车押金仍在鲁师傅那里；他没有把未来结算提前写进余额，也没有把手腕当作已经修好的零件。"],"next":"c10-s01"},{"id":"c10-s01","chapterId":"c10","chapterNumber":10,"title":"到账与第一笔缴费","location":"翔子的房间与家乡电话","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["10月3日，翔子收到九月结算4950元。他先没打开觅单，而是把结算通知从头读一遍：订单报酬、补贴、出勤奖励和服务调整排成几行，下面只有一个到账总数；五个没去上班的班次没有单独标出。","他把银行卡余额和上月末的账对了一遍。9月3日到账6260元，扣掉租房、车租、饭钱、家用和摔车后的860元，月底余额是9920元。加上今天的4950元，十月日常开支3740元已经排在前面，许福兰的报名费还没算进去。翔子把缺五班、结算少分成两行，没有说这4950元全是摔车造成的，也没说差额以后一定会补。","当天晚上，母亲发来学校缴费清单照片。许福兰问过老师，报名和第一笔材料、住宿费合起来要1200元，正式学费可以晚些交。翔子把照片放大逐项读了一遍，确认不是母亲临时凑出的估数。母亲说可以先问亲戚借一部分，许福兰却在旁边提醒哥哥按他能给的来，她已经问过学校，书本费可以晚交。","翔子没有马上回我全出。他把车票背面摊在膝头算：期初9920元，加结算4950元，扣十月正常开支3740元，再转家里1200元，月底预计还剩9930元。他把数字发给母亲，说这一笔可以先转，剩下的费用得等11月3日结算。母亲答应先交这一笔，再和许福兰想后面的办法。","转账完成后，许福兰发来缴费页面截图，状态显示已受理。她没说哥哥救了她，只把下一次费用记进学校通知本。翔子看着那行绿色小字，想起自己第一次看到账单里的待结算时，还分不清哪笔钱真的进了账户。1200元已转出并受理，正式学费仍可后缴；他没有把未交的费用记成已付。"],"next":"c10-s02"},{"id":"c10-s02","chapterId":"c10","chapterNumber":10,"title":"课程表上的两个问题","location":"职校走廊与电话","background":"office","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["十月上旬，许福兰把课程表拍给翔子。表格分理论课和实训课，几个课名她不太懂。她没有问哥哥选哪门，只在照片旁列了两个问题：实训从哪学起，方向什么时候定。翔子先打出选你想学的维修，又觉得自己仍在替她圈答案，删掉后只回：问清课程，再自己选。","两天后，她发来语音：下课后拿着课程表到办公室外等，老师正和另一名同学说话，她就在走廊把问题又读了一遍。轮到她时，她先问实训从哪里开始、什么时候能自己选方向，没有问哪一门以后工资高。老师指着课表说明理论课和实训课的先后；具体方向要等课程安排下来，再看她学起来怎么样，不用只凭课名决定。","许福兰把实训安排待通知写在页边，又追问最早什么时候出安排。老师说还要等学校通知，她把日期空着，没有替对方填一个猜测。她在语音末尾说，现在还没到选的时候，再听几节课后自己决定。翔子没有把维修经历发过去劝她，只回：好，等你问清。"],"next":"c10-s03"},{"id":"c10-s03","chapterId":"c10","chapterNumber":10,"title":"休息日的问号","location":"北桥站","background":"office","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["十月中旬，站里贴出月底考勤安排。正常排班的出勤奖按当月方案计算，休息日若愿意顶班，还能另拿一笔补助。报名不是强制的，不去不影响原排班考勤，只是少一笔额外收入。翔子把表拍下来，发现自己的休息日旁边被铅笔写了个问号。","那天他刚跑完一段平常的主路，右腕没有再麻，手指根却被刹把压出浅红印。马力问要不要报名顶班，翔子没有立刻答，把手机收进兜里，先松开护腕透气。他原想趁那天去附近看修理铺，问有没有能从小活做起的地方；另一边，临时顶班会有补助。"],"choice":{"flag":"c10_rest_focus","prompt":"在这次顶班取舍里，先把哪一点记进记录卡？","options":[{"value":"wrist","label":"手腕仍发紧","note":"记录卡：右腕没有再麻，手指根仍被刹把压出浅红印。"},{"value":"repair_shop","label":"想去看修车铺","note":"记录卡：翔子原想趁休息日去附近看两家修车铺。"}]},"next":"c10-s04"},{"id":"c10-s04","chapterId":"c10","chapterNumber":10,"title":"在站点答复","location":"北桥站","background":"office","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["翔子在同意顶班旁边停了很久，最后把手机递给马力看：我休息。马力在站点表上把那天留空，没有拿合同吓他，也没把不去写成态度问题，只说常规排班不动，休息日顶班补助就没有。翔子把日期记在本子上，写下没接顶班、少一笔补助，换一天看店、睡够。"],"next":"c10-s05"},{"id":"c10-s05","chapterId":"c10","chapterNumber":10,"title":"问两家修车铺","location":"附近修车铺","background":"shop","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["休息日，翔子还是去了周围两家修车铺。第一家的卷帘门只开一半，老板正把内胎从轮圈里撬出来。翔子等他装回轮胎，才说自己会修灯线和接点，也做过换胎。老板问一天能换几辆，他说没在店里计过数。","老板摇头，说店里就他一个人，来了活自己做，暂时不招人。翔子没有留下白干，只问附近有没有招人的铺子；老板说不清楚。第二家墙上挂一排电池，师傅正查接点。翔子说想找能从小活做起的帮工，周末和休息日有空。","师傅问能不能拆电池壳，翔子说不会做，也不接这种活。师傅说新人可以先学换胎、修灯线、判断外接接口；电池壳里的故障要设备和经验，不能拿顾客的东西练手。师傅问能否每周固定来半天，翔子说班次由站点排，休息日看当月表，没法先承诺固定星期几。对方没催，只把他的号码写在便签上；翔子记下店名和基础活，没有把这次问话算成一份工作。"],"next":"c10-s06"},{"id":"c10-s06","chapterId":"c10","chapterNumber":10,"title":"留在日历上的空格","location":"站点与房间","background":"night","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["下午回房间后，翔子睡了几个小时。醒来时手腕没再发麻，他没有在路边接单，也没觉得这一天白过；只是翻账本时，没接的那笔顶班补助仍是一个看得见的数字。休息没有把那笔补助变成已拿到的收入；十月结算仍要等十一月三日到账。","休息日后的第一个正常班，他把护腕缠得比平时松一点，先走熟悉的主路。接完几单后，腕子只是发紧，没有再麻到手指；他在红灯前活动两下，再把手放回刹把。休息没让伤口凭空消失，但他不必一醒来就把多接一班当成唯一选择。","何师傅看见他翻考勤表，手指在膝盖上敲了两下，说自己以前也觉得少跑一天就少吃一天饭，后来才知道有些天是腿不肯再替人算账。翔子问他什么时候开始觉得膝盖不对，何师傅说不出哪一天，骑久了就肿，歇一晚又好一点；他以前总把好一点当成还能继续跑的凭据。他没有让翔子学着停或学着硬扛，只把膝盖护套往上提了提，起身时扶了一下车把。","月底翔子把银行卡余额核到9930元，十月正常支出和家里1200元额外款都已算入，九月伤后开支已在期初余额里；十月工作结算要等11月3日到账。租车押金500元仍在鲁师傅那里，房屋押金900元也没回来。他在休息栏旁画了小勾，车价5700旁边仍留空白。"],"next":"c11-s01"},{"id":"c11-s01","chapterId":"c11","chapterNumber":11,"title":"通知上的期限","location":"北桥站玻璃门","background":"station","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["11月1日，北桥站玻璃门上贴出新的电动自行车登记规定：11月1日以前购买、尚未登记的车辆，应在次年4月30日前办理首次登记。翔子站在门口看两遍，先确认日期，再把通知拍下来。","小路凑过来读。他夏天买的车一直没登记，发票和整车合格证明都放在老家，问自己的车是不是也要办。翔子说通知写的是十一月前买且尚未登记，先核实车型和材料，不要只看车牌旧不旧。","站里有人说新规要把老车都收走。马力过来把通知重新贴平：公告写什么就按什么来，别替交管部门加一句；谁的车要办什么，先把情况弄清。翔子看向自己的租车，又想到夏天看过的蓝灰旧车。那车已有登记牌、车型在北京目录里，不属于通知里的未登记车辆；他给鲁师傅发消息，问车还在不在。"],"next":"c11-s02"},{"id":"c11-s02","chapterId":"c11","chapterNumber":11,"title":"结算到账后的盘算","location":"站点与房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["11月3日，佑路把十月结算6200元打进翔子的银行卡。十月月底余额9930元，加上结算后显示16130元；他先给日常开支分出3740元，其中有房租、公共费用、租车、吃饭、家用和零碎开支。到11月15日，房租和车租照常交完，500元租车押金仍在鲁师傅那里，得等交回车才退。","翔子没有把一万多看成车价外的闲钱。表哥的借款早已还清；买车还要考虑电池、修理和没到账的下一笔工资。他把每月450元车租与买车后多留的维修费放一起算，常态支出只会少两百多，5700元不是几个月就能省回来的钱。","他仍想买，却没把自己的车说成稳赚的买卖。若这次不买，租金照付；若买，备用电池和冬天续航也不保证。11月1日前购入、尚未登记的另一类旧车要在次年4月30日前首次注册，那是小路的期限，不是这辆已有登记牌车辆的过户期限。翔子把两种情况分开记在纸上，没有把押金当成可随手使用的钱。"],"next":"c11-s03"},{"id":"c11-s03","chapterId":"c11","chapterNumber":11,"title":"再看一圈蓝灰车","location":"鲁师傅的铺子","background":"shop","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["11月24日收工后，翔子把租来的车骑到鲁师傅铺子。蓝灰色旧车还在里面，前轮下垫着木板。鲁师傅说这几个月有两个人问过，嫌备用电池旧，最后买了别的车；价格没改，配件也没有换新。","翔子把车推出来，检查轮胎、刹车、车灯和电池接点。主电池充满后，他绕附近街口骑一段，电量格没立刻下降，刹车也没异响。备用电池还是旧的，短试时仪表往下跳一格，仍看不出能跑多远。鲁师傅不保证冬季续航。","鲁师傅把行驶证和车辆登记材料放在柜台，翔子对车架号、车型和车主姓名。材料显示登记在鲁驰名下，与车辆对得上。翔子问备用电池衰减，能否降价。鲁师傅说按现状卖，5700元含随车旧备用电池和一次基础维修工时；换电池、接点等零件材料另计，不附带冬天能跑多少公里的保证。"],"next":"c11-s04"},{"id":"c11-s04","chapterId":"c11","chapterNumber":11,"title":"办理转移登记","location":"登记点窗口","background":"office","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["鲁师傅说要办手续可以当天一起去，让翔子证件带齐，车也带上，材料不懂的当场问。翔子拿出身份证，和鲁师傅填好转移登记申请表，签下原始买卖协议。两人带车去登记点，在窗口外排队。翔子看到墙上仍贴着新规通知：有人带未登记旧车资料来问首次登记，也有人像他们一样为已经登记的车办转移。","轮到他们时，工作人员分别核对买卖双方身份证明、原始买卖凭据、车辆登记材料和行驶证。翔子报车架号，按窗口要求把车推到查验处；工作人员对照证件检查车架编号，确认车型、牌照和登记人一致。问到原车主时，鲁师傅本人回答，没有由翔子代说。","材料核验齐全后，工作人员按转移登记流程办理所有权变更，登记不收工本费。骑到窗口、排队、交验再回来花掉的时间，没有出现在翔子的结算单上。车牌还是原来那块，登记信息改为许翔的名字。办的是已登记车辆的所有权转移，不是小路那辆未登记旧车的首次注册。"],"next":"c11-s05"},{"id":"c11-s05","chapterId":"c11","chapterNumber":11,"title":"车主名字换了","location":"租车点与回房路上","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["回租车点时，翔子把租赁车交还给鲁师傅。11月15日已交的450元是当期租费，按约不退；车身没损伤，只有500元押金退回。鲁师傅把押金交还后，翔子核对收款姓名，转出5700元车款，备注二手车购车款。鲁师傅写下收款条，与原始买卖协议一起交给他。","按本月常态支出已付后的余额12390元为底，加回押金500元、减车款5700元，银行卡约剩7190元。租车账少一行，账户也薄了一截；房屋押金900元仍在高姨手里，不能当成下一块电池的钱。翔子把登记凭证收进文件袋，骑着新车回房，坑洼路上车篮里的工具轻轻碰了一下。","第二天早上，他照常把车推到站点门口，先试灯、捏刹车、检查车篮里的工具。排班表没有因为车主姓名变了空出一格，第一单仍从熟悉的街口开始；入口、取餐时间和送达倒计时也没变。他没有带文件袋上路，只在日常使用中留意新车的手感。","小路把工牌背面的日期翻给他看：4月30日，时间还够。翔子把新行驶证收好，说够不够要看材料；先把车和票据找出来，办时他陪着去，但申请人是小路自己。夜里，翔子在账页上划掉车5700，写下维修和电池另算。车是自己的，不等于多出一张可以自由安排工作的时间表。"],"next":"c12-s01"},{"id":"c12-s01","chapterId":"c12","chapterNumber":12,"title":"新车的冬日账","location":"翔子的房间与楼下","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["12月3日，十一月结算到账5900元。翔子把短信里的月份抄在银行卡余额旁：上月底7190元，到账后13090元。房租、水电、吃饭、通信和寄家里的650元仍要从里面出去；这笔钱是上个月跑出来的，不是今天跑完就有。","他骑自己的车，不再向鲁师傅交450元月租。十一月交接单还压在床头，车牌已登记在自己名下，租车押金500元也退回了。翔子推车到楼下，拧开电门试过，没有把省下月租直接写成收入，只在车辆栏记下电费与维修预留300元。"],"next":"c12-s02"},{"id":"c12-s02","chapterId":"c12","chapterNumber":12,"title":"电量格不是路程","location":"冬日街路","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["入冬后一个晚班，翔子骑回站时主电池只剩两格。车篮里的备用电池表面还亮四格，外壳摸上去却冷得发硬。他没把四格当成能跑多远的保证，只在本子记下：主电池低温掉格，备用电池还没带负载试过。","那晚他按熟路回住处，没有为了凑单量再往远处绕。到了楼下，他把两块电池状态放在同一行，却没把尚未试过的备用电池算作可靠续航。电量格会变，温度也会变；他只记下当时看到的，不替明天的路作保证。"],"next":"c12-s03"},{"id":"c12-s03","chapterId":"c12","chapterNumber":12,"title":"备注只写了不要敲门","location":"便当铺与住宅区","background":"night","portrait":"luojie","portraitLabel":"","speaker":"旁白","pages":["十二月中旬一个晚上，骆姐的便当铺快打烊时又来一单晚饭。灶火关小，打包台仍挤着几份待取餐。骆姐对着订单号，把汤盒、筷子和餐巾纸分开装，免得两单混在一起。手机备注写不要敲门，地址却只到小区，没有楼门。她确认汤没漏，才把袋子递给翔子，提醒先问清楚，别替顾客猜。","地图箭头停在小区围墙南侧，入口却在另一条街。翔子看了眼时间，没有先点送达，而是打电话问顾客在哪个门。电话里有风声，对方说从南门进，右边那排楼，三号楼前有棵树，住二单元；别按门铃，孩子睡了。翔子重复楼号和单元，又问能不能把饭放门口。顾客说可以，到了再发消息。","骆姐听见后在小票边写下南门、二单元，免得下次再错。翔子没把这行手写补充当成平台备注，只在手机重新记一遍。他把车停在南门外，推车进去。保安只问是哪栋，他报楼号后沿树往里走，车轮压过一层落叶，发出细碎声响。","他没把饭放门岗，也没提前点送达。到了二单元门口，他把保温袋放在脚边，发消息说已到。屋里没有马上有脚步声，他把手从门铃旁收回，靠墙等。顾客只打开一道门缝，伸手接饭，压低声音说谢谢。翔子把手机举低，只拍袋子和门边一小块地砖，没有拍进屋里的人；门轻轻合上，他才点完成。","系统计时没有因为电话确认地址停下。订单页只留实际送达时间，没有写他在门口等多久，也没保存南门和二单元这段通话。顾客没有留长评，骆姐也没判谁对谁错；不要敲门帮翔子避开一个错误动作，却没替平台补上楼门和路口。"],"next":"c12-s04"},{"id":"c12-s04","chapterId":"c12","chapterNumber":12,"title":"把待确认的事项分开","location":"站点门口","background":"station","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["收工回站时，宋嘉欣接到家乡一家餐馆的电话。她走到门外听，手里拿着写过字的纸。对方先问什么时候能回去，她没有马上答，先问每天几点上班、晚班到几点、每周休几天、工资按月还是按班结，以及店里能不能提供住处。","电话那头说能安排员工宿舍，但不能带孩子住。宋嘉欣问若住在母亲家，能否排固定早班；休息日能不能提前知道，好安排女儿放学。对方说岗位还没最后定，宿舍和排班等店长回来再确认。她没因可以提供住处就答应回去，只说还要和母亲商量接送，第二天再回电话。","她把店名、联系人、通话日期和宿舍不带孩子写在纸上，挂断后折进钱包。母亲随后转来女儿联系册照片，老师在页角标了家长签名，照片拍得有点斜，下面签名栏仍空着。宋嘉欣放大看，给女儿发语音：周五下班给她回电话，让她念当天那一页，今天先让姥姥签。她没答应哪天回家，只把这通电话定下来。","她把纸摊在门边台阶上，已答清的写左边，等店长确认的写右边，固定早班、住母亲家、女儿放学谁接都画问号。她加上明天回电，没有给任何一项打勾。翔子让出门口，没有替她把问号改成答复。","周五收工后，宋嘉欣在站点门口给女儿回电话。孩子把联系册从头念一遍，姥姥说签名已经补上。宋嘉欣没有马上讲求职，只让女儿把本子放回书包旁；挂断后，她才把仍等店长回复的工作纸折回钱包。"],"next":"c12-s05"},{"id":"c12-s05","chapterId":"c12","chapterNumber":12,"title":"冬季修缮按原清单","location":"家中摊位","background":"home","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["月底，母亲发来老家窗台结霜的照片，说摊位棚布边沿裂了，灶间水管接头也开始渗水，要先换接头、补棚布。她把师傅写的材料和工钱单拍给翔子看，合起来800元。翔子问还要不要另买东西，母亲说这笔够了，他才把钱转过去。母亲回收到了，别再多转；翔子在本子上单独写冬天、家用800元。","年底对账前，母亲发来棚布补好后的照片和收条。修补处沿旧边缝回去，磨白的布面还在，没有换整张新布。师傅按原清单补边、换水管接头，开水试过后接口没有再渗；收条项目和转账前的清单对得上，没有另加项目。","许福兰解下临时系着的旧绳，沿新压住的棚布边缘按一遍，又用手背轻轻碰接头下方，确认没有水珠。母亲说这回收摊不用再临时系绳。许福兰把收条夹进家里的文件袋，指尖在没补到的磨白处停了一下；翔子把照片和收条存到原转账记录旁，没有另列一笔支出。"],"next":"c12-s06"},{"id":"c12-s06","chapterId":"c12","chapterNumber":12,"title":"年末仍有一格电","location":"翔子的房间与楼下","background":"night","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["12月31日，翔子把银行卡余额和账页对了一遍：十一月结算5900元，购车后常态支出3500元，家里冬季额外800元，期末现金8790元。十二月跑的单还要等1月3日结算，他没有提前写进余额。","他把钥匙放在桌边，登记凭证收进文件袋。车是自己的，什么时候上线仍要看排班和订单。下楼前，他在车把旁留下手写标记：电量格低于两格，不走远路。冬天两块电池状态不同，备用电池没有带负载测试过。"],"next":"c13-s01"},{"id":"c13-s01","chapterId":"c13","chapterNumber":13,"title":"先记下电量","location":"北桥站外","background":"station","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["一月三日，翔子收到十二月的结算款：五千六百元。他把数字写进收入栏，先把它和上月底八千七百九十元的余额相加，手机银行显示一万四千三百九十。三千五百元常态开支还要从里面留出，备用电池的钱没付之前，他不把那笔钱写成已经剩下的余额。","买车以后，他不用再向鲁师傅交月租，可出门前先看的不是省下多少，而是仪表上的电量。冬天温度低，旧电池有时在楼下显示四格，到了午后便只剩两格。格数会变，不能直接回答还能走多远。翔子把充电器和手套放进车篮，开始在账页旁画一张小表。","表上没有复杂算法：出门时几格、收车时几格、当天跑了几单，手腕有没有酸。他想把一句“今天不对劲”拆成几个能核对的项目。旧电池不会因为他写下数字就恢复；但如果问题先出在电量或身体上，他至少不必等到路上停下才想起来。","他没在表格上填一个固定里程，把几格电硬换成能走多远。那得看实际负载和路况，靠一次短路猜不出来。他把“待核”留在旁边，等第二天测完再记；这页只帮他保留观察，不替电池作保证。"],"next":"c13-s02"},{"id":"c13-s02","chapterId":"c13","chapterNumber":13,"title":"路上的断电","location":"居民区外侧道路","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["一月中旬的一单还没送完，备用电池忽然掉了格。翔子骑到一半，电机声先闷下去，仪表从两格跳成一格，随后整屏黑了几秒。他把车推到路边，先确认自己离车流有一段距离，才拔下电池看外壳。卡扣没断，接口也没有烧黑。","他没有拆电池壳，只把电池重新插回去，等了半分钟再拧电门。车子又能启动，订单却还在路上。他把剩下那段路骑得很慢，到商户门口时电量又往下跳了一格。回站后，他没把这次短暂恢复当成电池已经没事，问鲁师傅能不能替他测一遍。","鲁师傅让他先把备用电池放在店里充满，第二天再看掉电情况，不要只凭一次跳格就买新的。翔子把电池留下，按原来的方式收好随身物件，没有把“车还能启动”写成检查结果。那天的订单已经送完，但这块所谓的备用电池，暂时不能替他多添一段可靠路程。"],"next":"c13-s03"},{"id":"c13-s03","chapterId":"c13","chapterNumber":13,"title":"九百元写清楚","location":"鲁师傅修车铺","background":"shop","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["第二天清早，鲁师傅把检测夹接到电池外面的端子，先看静置电压，再让翔子在店门外带负载转一圈。充满的备用电池骑一小段就掉到两格，停下来仍会往下跳。鲁师傅又接上主电池作对照，仪表稳定得多。翔子看着两组读数，没有再把问题全归给天气。","检测仪上的变化指向旧电芯留不住电，接点也有磨损。鲁师傅没有撬开电池壳，只说这种电芯不适合在店门口临时拆换；如果继续拿它跑远单，路上可能突然断电。翔子把结果抄进本子，写下“旧备用，负载后掉格”，然后问有没有不拆壳的处理办法。","“电芯我不建议你开壳换。可以找一块检测过的二手电池，接点也要换，材料一共九百。”鲁师傅说。翔子追问电池从哪来、能不能装进自己的车，又确认这次检查和装配是否使用购车时附带的基础维修工时。鲁师傅翻出交接条目：那次工时还在，九百只收替换电池和接点材料。","翔子拿着收据逐项看过，才买下那块检测过的二手电池。寿命和冬天续航没有被写成保证。装好后，他把车推到门外试骑，电量格没有立刻往下跳；这只能说明当下能用，不能说明能用几年。九百元的实际用途和不保证的部分，都留在同一张纸上。","一月的账页多了一栏。他原本把买车看成每月省下四百五十元，却没料到冬天还要为备用电池和接点材料另付九百。他没把这点试骑结果写成“故障解决”；旧电池的问题有了检查记录，新电池也只是被测过、装上，并不是全新的长久承诺。"],"next":"c13-s04"},{"id":"c13-s04","chapterId":"c13","chapterNumber":13,"title":"把空格留着","location":"社区门诊与房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["低温和长时间握把让右手腕再度酸胀。翔子去社区门诊复诊，医生让他握拳、转动手腕，问疼痛是不是只在骑车后出现。翔子说白天握把时还能忍，停下来才觉得发紧。医生看过活动范围，让他戴牢护腕，必要时停一天，不要拿“还能动”代替恢复。","“停一天就会好吗？”翔子问。医生没有替他定期限，只说先观察，肿起来或者麻到手指再来。那次复诊的开销从本月零碎医疗费里出。后来，何师傅陪他在站点附近走熟路。翔子把车停在路边，揉着手腕看一笔送往外侧居民区的晚单。","蓝线穿过一条窄路，路面有薄水，一盏路灯没亮；替换电池刚装不久，仪表只剩两格。何师傅看了看他的手和电池，说：“新换的电池还没跑过长路，手也酸，别拿那几分钟去赌。”翔子看了眼倒计时，又看了看湿路和两格电，最后把这笔单退回站点允许的处理流程，没有拐进窄路。","单量少了一笔，他仍然懊恼，却在记录里写“拒绝绕行，少跑一单”，没有写成“今天没本事”。次日，他按医生建议休息一天；记录表仍写着腕部发紧，不把休息当成已经恢复。车还在楼下充电，仪表格数没有因他盯着看而多出一格。","月底的结算预览又出现一条“到店延迟”。订单号他认得，本子记着当天进店时间，骆姐的小票也写过实际出餐时刻。照片只能证明他按过快门，不能独自证明当时已经到店；平台预览没有列出具体分钟，只留类别和订单号。翔子先把它圈成“待核”，没有提前算成银行里的最终扣款。","一月三十一日，他按账本把一万四千三百九十减去三千五百元常态开支，再减九百元电池和接点材料，余额是九千九百九十。那条调整还没成为实际到账金额，他把它留到二月再核；设备能用、手腕仍紧、结算未定，各占各的一格。"],"next":"c14-s01"},{"id":"c14-s01","chapterId":"c14","chapterNumber":14,"title":"四栏先对同一单","location":"站点收工后的折叠桌","background":"station","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["一月三十一日晚上，宋嘉欣看见翔子把手机截图和小票叠在一起，问那条服务调整查到了没有。翔子说预览里只有订单号和“到店延迟”，看不出系统依据的是哪一个时间。他打开帮助页，页面只说如需核对就联系站点，没有把延迟的分钟数写出来。","宋嘉欣没有先说该投诉谁。她把小票放大，汤水洇过一位数字，订单号和日期仍能看见；又拿便签分出四栏：订单号、到店时间、商家实际出餐、送达时间。“如果只拿手机里的一格去问，别人只能回你另一格。得把同一单的几边放在一起。”","二月一日收工后，站里几个人围着一张折叠桌，把订单页、商家截图、小票和相册照片摊开。小路找到一单午饭记录，商家端的备餐时间挤在另一张订单行里，尾号对不上；胶带哥的照片能看到取餐台和时间，却没有订单号。翔子那单平台到店时间比手记晚了十几分钟，骆姐小票上实际出餐时刻也对得上日期。","宋嘉欣负责排材料顺序，翔子逐一核订单号，小路找出商家端截图，胶带哥按日期把缺号照片发来。宋嘉欣把争议订单的日期和门店发给骆姐，问收摊后能不能核一遍；骆姐说关火后再找，没有从记忆里立刻认领那张照片。","宋嘉欣把翔子的单放在中间，胶带哥的照片夹进“待核”栏。她问翔子：你现在先想把哪一项放在记录卡上提醒自己？"],"choice":{"flag":"c14_focus","prompt":"记录卡先标哪一项？","options":[{"value":"order_id","label":"先核订单号","note":"记录卡：先用订单号把平台、个人和商户记录归到同一单。"},{"value":"merchant_time","label":"先核出餐时间","note":"记录卡：先看骆姐小票上的出餐时间；照片仍需订单号对应。"}]},"next":"c14-s02"},{"id":"c14-s02","chapterId":"c14","chapterNumber":14,"title":"没号的照片留待核","location":"骆姐便当铺打烊后","background":"shop","portrait":"luojie","portraitLabel":"","speaker":"旁白","pages":["收摊后，骆姐清出打包台的一角，把沾着油和汤水的小票按日期摊开，再对着商家端逐行核订单号和手写的出餐时间。","能看清号码的夹在一边，只有时间、尾号洇掉的仍放回“待核”。胶带哥说自己记得那天等了快二十分钟，骆姐没有否认他的记忆，只说这张照片没号，她不能说就是那一单。她也不可能在午高峰每单多抄一套账；留下来的几张只能证明各自能对上的部分。","翔子把平台页面转给骆姐。两人对过日期和号码，她才拍回小票局部：画面只留订单号、日期和出餐时间，顾客姓名和电话被折到下面。她只确认这是自己写下的时间，不替骑手判断平台扣款该不该改。","胶带哥把当日订单页翻了几遍，仍没找到照片对应的单。他照宋嘉欣给的空白便签，自己写下“订单号、到店、出餐、送达”，又在路线本补了一句：拍照前先留单页，转发前遮住顾客信息。那张照片仍留在“待核”，没有被改写成证据齐全。","另一张订单截图露出顾客的电话号码和详细地址。宋嘉欣没有转进群里，先让骑手遮住个人信息；交给马力核对时，才把完整原图单独交过去。翔子也从自己的纸表划掉顾客姓名，只留下订单号、商户和时间。那张表要说明一单发生了什么，不需要把顾客写进他们的账。","宋嘉欣把清楚的小票局部归进可复核材料，尾号缺失那张仍留待核。骆姐把没拍走的票据收进抽屉，转身清台、收汤盒；午高峰留下的纸不全，店里也得照常打烊。"],"next":"c14-s03"},{"id":"c14-s03","chapterId":"c14","chapterNumber":14,"title":"能证明的与待核的","location":"马力办公室门口","background":"office","portrait":"ma","portraitLabel":"","speaker":"旁白","pages":["马力起初不想把一叠截图直接报到公司。他让翔子按订单号排好原图，自己拿站点结算打印页进了办公室。门关了一会儿，里面传来翻纸和敲键盘声。马力出来时手里多了一张复核记录：一单的商家备餐时间记到了另一张订单，另一单的平台到店时间比骑手照片晚了十几分钟。","马力也考虑着站点续约，不想一上来把这些截图全部报成站点投诉。公司系统里虽有调整金额，但能和订单号、商家材料对应的只有两项；其余几单缺少凭证，他没有把它们混在一份上报里。","“其他几单只有你们记的分钟，没有小票或订单号能对应，我不能替你们说成系统错了。”马力说。翔子问还要不要报，马力把纸推回来：“报。只是能证明的和不能证明的得分开。我能让公司复核，不能保证每一笔都改。”","二月二日，马力接到公司回电，拿笔在站点记录本上逐条记。公司确认两单的时间记录有错位，相关调整会在这次结算里回拨一部分；另几单因为缺少能对照的商户记录，维持原结果。没有“全部撤销”的通知，也没有单独转账的承诺。","马力提醒他们到账时要对总数，别以为复核通过就会另有一笔钱。宋嘉欣把公司的回信存好，翔子则把两张小票夹回文件袋。追回的只是一部分，其他空格还在那里；能核的先提交，不能核的仍留作待核。"],"next":"c14-s04"},{"id":"c14-s04","chapterId":"c14","chapterNumber":14,"title":"四千七百已经包含回拨","location":"房间账页旁","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["二月三日，银行卡到账四千七百元。翔子没有把这笔钱拆成“结算款”和另一笔追回款；这四千七百已经包含公司复核后回拨的一部分，不会再另外打来一笔。","上月底余额九千九百九十，加上四千七百，合计一万四千六百九十。二月常态开支三千五百还要先留好，预计可用余额是一万一千一百九十。这个数仍没扣掉月底另外出现的家庭事项，也不是可以随便花的全额。","他把结算单、两张小票和复核记录按同一订单号放好。没有补回的部分仍没变成已解决；照片不能代替缺失的单号，站点也没有许诺把每一笔都改回来。翔子在账页上把“部分回拨，已含本次到账”写清，之后的核对就从这个总数开始。"],"next":"c15-s01"},{"id":"c15-s01","chapterId":"c15","chapterNumber":15,"title":"膝盖不按排班表走","location":"北桥站门口","background":"station","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["二月中旬，何师傅扶着车把站了一会儿，没有马上跨上去。旧护具套在膝盖外，裤脚被风贴在小腿上。他看了看电池格，把脚从踏板上放下来，像是在等腿里的那阵疼过去。","“今天不跑？”翔子问。“先等一会儿。昨天从楼梯下来，晚上就肿了。今早好一点，骑上去又不舒服。”何师傅说他看过医生，能走，但别一天跑太久；排班表却不会问身体能不能撑一整天。","他说完还是骑上了车。翔子没有追上去劝，只记住那句“别一天跑太久”。下午，他们又在小区台阶边碰见。何师傅右手扶栏杆，左手推车，车不重，膝盖却不肯跟着抬。翔子过去托住车尾，何师傅低声说“我自己来”，像是给自己留一点地方。","车上了平地后，何师傅坐在长椅上等酸胀退下去。他说站里不缺单，缺的是把一天拆开来过的办法。修车他能做，坐着也能做，抬重的少一点；只是他不想等到被人看成不行了，才去找另一种活法。翔子问鲁师傅那里是不是还需要人，他没有替何师傅答应，只说可以帮忙问联系方式。"],"next":"c15-s02"},{"id":"c15-s02","chapterId":"c15","chapterNumber":15,"title":"先坐下来试半天","location":"鲁师傅的小铺","background":"shop","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["翔子去鲁师傅的店里问最近需不需要半天帮手，说清楚是何师傅想了解，不是替他承诺。鲁师傅把扳手放回桌面，说明早上来、下午前走，忙的时候再问；不忙就坐着分零件。工钱按做完的活计算，不会比跑单多，也没有半天保底工资。","翔子把时间、站多久、重活能不能换人这些话带回去。何师傅没因一句“能坐着”就答应，问清楚后才决定先试几次。第一天，鲁师傅让他坐矮凳分拣螺丝和灯泡。何师傅习惯性想站起来取工具，鲁师傅把扳手推到凳边：“坐着也够得着，不用每回都起身。”","腿活动开后，鲁师傅让何师傅检查一辆车的刹车灯线。车主站在门口问是不是灯泡坏了，何师傅没先猜。他请车主捏刹把，自己看红灯何时熄，再轻晃车尾。灯泡没裂，接点却松了。他压紧线头，让车主连续捏三次刹把；三次都亮，才装回灯罩。","何师傅只说这次接点压实了，不替以后作保证。车主推车离开，他站起身，膝盖没立刻发软，却也没一口气做完几辆车。店里安静时，他坐回矮凳把螺丝按大小放好。排好的半天不会自动长出工钱；没人来修，手边就没有完成的活。"],"next":"c15-s03"},{"id":"c15-s03","chapterId":"c15","chapterNumber":15,"title":"排班时段不是保底工资","location":"修车铺柜台边","background":"shop","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["快到中午，鲁师傅把一碗面放到柜台边，叫何师傅先吃。何师傅问忙的时候要不要帮着抬电池，鲁师傅说重活另找人，不让他逞强；半天只是排定的时段，钱仍按当天做完的活计结，活少就少挣。","挣得比跑单少，休息时间却能写进安排里。何师傅听完没有马上说好，先问下一次什么时候能来。几次试下来，他才回小铺问能不能把半天排进下周。鲁师傅拿出旧日历，和他圈出能来的日期，旁边写明“按做完的活计钱，重物另找人”。","何师傅把纸折好收进护膝外侧的口袋，回站点找马力，说下个月不再排整天常规班，偶尔顶一段会提前说。马力没有劝他留下，只把新的班次从排班表上划掉，问要不要保留群消息。何师傅说先留着，万一有人要修车还能联系。","那一笔被划掉后，何师傅没有当场脱下反光背心，只把它叠好放进工具袋。他不是倒下了才被送去别处，也不是靠翔子救走；他只是在身体还能做事的时候，自己先挑了个能继续做下去的节奏。旧账、收入和膝盖不会因为换一张排班表就一起清零。"],"next":"c15-s04"},{"id":"c15-s04","chapterId":"c15","chapterNumber":15,"title":"等实训通知","location":"站点休息处","background":"station","portrait":"fulan","portraitLabel":"","speaker":"旁白","pages":["二月中旬，翔子收到许福兰的语音。学校发了实训流程预告，具体实习单位名单还没公布。她课后自己去问老师，老师说学校会统一安排，时间确定后再通知。她没有等哥哥替她打电话，只把“什么时候公布、之后找谁确认”记进通知本。","她发消息告诉翔子：“我记了，等通知出来我自己去问。”翔子回了一个“好”，没把自己的判断塞进她的计划里。名单尚未定，时间也没有定；她能做的是把下一次询问写清楚，再按学校通知往下走。"],"next":"c15-s05"},{"id":"c15-s05","chapterId":"c15","chapterNumber":15,"title":"额外六百单列","location":"房间账本旁","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["二月最后几天，母亲发来消息，说许福兰后续实训材料和家里常用药还差六百元。翔子先问是不是当天就得付，母亲说月底前补上就行。这个月按原约定的固定家用已经转过了，他没有把这次缺口混进那一笔里。","他又转了额外六百，在账页“家用额外”一栏单独记下。二月三日到账的四千七百已经含有一部分回拨；月底对账时，他以一月末九千九百九十为底，加四千七百，再减三千五百常态开支和这六百，余额一万零五百九十。何师傅的工钱没有写进翔子的账，鲁师傅的铺也不是翔子的店。"],"next":"c15-s06"},{"id":"c15-s06","chapterId":"c15","chapterNumber":15,"title":"待装车试灯","location":"房间桌边与北桥站","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["何师傅离开站点前，把旧车上拆下来的刹车灯交给翔子：“这只还亮，你看看接点。别急着拧，先找松在哪儿。”翔子回房后把灯放在桌角，用小螺丝刀打开外壳，没有急着剪线。焊点没裂，弹片却压得太平，轻轻一碰就松。","他把弹片挑起一点，擦掉接口里的灰，再合上灯罩。没有换零件，也没有立刻把它写成“已经修好”，只在纸上记“弹片回位，待装车试灯”。第二天到站，胶带哥问弹片回位是不是就算修好。翔子说要装车复测，亮过一次不等于确认。","几天后，胶带哥照这套办法给一单普通午饭留了记录：到店先保存订单详情，再拍骆姐写了日期和出餐时间的小票，镜头避开顾客姓名与电话。回站后，两张图按同一日期放进相册，订单号和小票能对上。翔子只让他留原图，不保证平台一定改账。","何师傅的车不再天天停在站里，那只灯却留了下来。它不是告别礼物，也没有另算成翔子的维修收入；它还得等装回车上复测，才知道接点稳不稳。"],"next":"c16-s01"},{"id":"c16-s01","chapterId":"c16","chapterNumber":16,"title":"电话那头的班次","location":"北桥站外","background":"station","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["三月三日，二月的结算五千三百元到账。翔子把它写进账页，和上月底的一万零五百九十相加，再扣去三月常态开支三千五百，预计余额一万二千三百九十；没有另列一次性支出，也没把下一笔还没到账的钱算进去。","那周，宋嘉欣接到张家口县城一家餐馆的电话。她先在站点外听了一会儿，手机拿开看了眼信号，又走到门边继续。翔子没有走过去，只听见她问每月休几天、晚班到几点，女儿放学时能不能和同事换班。电话那头说岗位还在，工资比她现在跑单少，但时间固定，店里可安排员工宿舍。","宋嘉欣没有马上答应。她逐项问试工日期、工资发放日和排班表会提前多久出来，把对方回答的数字写在钱包夹层的小纸上，最后说要回去问母亲，明天给准信。岗位有了线索，却还缺孩子接送和实际班次的答案；她没把一句“能安排宿舍”当成已经能带女儿住下。"],"next":"c16-s02"},{"id":"c16-s02","chapterId":"c16","chapterNumber":16,"title":"把安排一项项问清","location":"站点门口","background":"station","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["第二天，宋嘉欣给母亲打电话。她把女儿放学后的接送、晚班怎么轮、宿舍离学校多远一件件确认。母亲愿意帮着接孩子，但不可能每天都等她下班。宋嘉欣没有把这句话听成拒绝，而是拿出女儿课表，先问母亲哪几天能接、自己哪几天能赶在放学前到家。","她把两种排法写下来，又问餐馆能不能固定早班，或把晚班集中到周末。电话里没有立刻谈妥，她们约好等店长确认班次后再算一次。翔子在旁边收工具，没有问她是不是累了才想回去，也没拿自己的车和存款当留下的理由。那是宋嘉欣的生活安排，不是等他替她添一项“留下来的理由”。","三月中旬，店长把班次逐项说清：早上八点到下午四点，周休一天，工资按月结，入职前先试做几天。宋嘉欣又确认晚班是不是偶尔才有、排班能不能提前一周知道，以及员工宿舍能不能带孩子。店长说宿舍给单身员工住，孩子不能住进去；她便改问住在母亲家能否固定早班。","班次表发来后，宋嘉欣把手机递给翔子看。时间和电话里说的一样，月收入比她现在的结算少一截。她又核对谁去接女儿、母亲能否临时替班，才回“我接受”，把入职日存进日历。她选择住母亲家，自己负责日常接女儿；首周临时延时的一次帮助没有被写成长期托付。"],"next":"c16-s03"},{"id":"c16-s03","chapterId":"c16","chapterNumber":16,"title":"回家后的一个小约定","location":"张家口家中","background":"home","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["宋嘉欣把入职日期念给母亲听，确认孩子接送后才说“我回去”。母亲会把空出的床铺收拾好，也提醒她不要把一次临时帮忙当成永久安排。她们说好先过一个月，再看上班和接送能不能顺下来。宋嘉欣没有说这条路一定好，只把试工那几天圈在日历上。","她又给女儿打电话。孩子问妈妈回去后会不会每天都在家，宋嘉欣没有把班次表说成保证，只说八点上班、四点下班，放学后尽量由自己去接；若临时延时，会提前和她们商量。女儿问书包能不能放在新床边，宋嘉欣让她先挑一本最想带回来的书。","孩子又问学校联系册放在哪里，妈妈回来后能不能给她看。宋嘉欣没答应“每天”，只说回家后先把联系册放在书包旁边，到家时一起看当天要紧的一页。女儿把这句话重复了一遍。宋嘉欣把“接女儿”写在入职日期旁边，不把孩子的安排留给翔子替她想。","四月第一周，一个平常傍晚，她按时从校门口接到女儿。孩子把联系册摊在桌上，指着老师写的“明天带彩笔”，有个字读错了。宋嘉欣没有替她念完整行，只把本子按平，等女儿自己看清再读；孩子重新念对，把本子合上放到书包旁。母亲在旁边掀饭锅，没有接过话。宋嘉欣看着这一页，没有把它说成日子已经全顺，只把当晚要做的小事做完。"],"next":"c16-s04"},{"id":"c16-s04","chapterId":"c16","chapterNumber":16,"title":"车票自己买","location":"站点门口与车站","background":"station","portrait":"song","portraitLabel":"","speaker":"旁白","pages":["两人并排坐在站点门口，翔子手里那杯豆浆已经凉了。宋嘉欣的手套放在两人中间，指尖几处线头松开；翔子把线头卷回去，她没有躲，只把杯子往他那边挪了一点。他想说“再等等”，又想到她已问过工资、班次和孩子接送，自己给不出更确定的一项。","翔子问她什么时候走。宋嘉欣说月底，票她自己买，母亲已经把住处腾出来，餐馆等她报到。翔子想把话说得完整些，最后只问要不要留下出餐便签。她笑说那是自己的本子，你有你的时间表；她只把一张路线复印页递给他，提醒南门晚间会锁，北门旁边的小道白天能走。","那天收工后，两人去街边吃了一碗面，谁也没有问以后会不会再见。宋嘉欣问车子冬天有没有出问题，翔子说换了备用电池，花了九百；她点点头，说自己的账里也留着回家路费。话到这里，两人没有把彼此的计划编成同一张表。","第二天，宋嘉欣在站点门口打开购票页面，把出发日、到站时间和餐馆报到日对了两遍，又给母亲发消息确认到站后谁来接、晚点时在哪里等。母亲回了一个能接电话的时间段，她才选定车次。票钱从她自己留出的路费里出，她把“车票已买”记进自己的账，没有让翔子垫付，也没写进他的本子。","三月二十九日，她把行李装进两只旧编织袋。有人问她以后还回不回来，她说不知道，先把女儿接回身边再说。翔子帮她把袋子抬到车站，走到检票口前停下。翔子说：“到了给我发个消息。”宋嘉欣握了握他的手，很快松开，又提醒他别总把有订单当成必须接。她进了检票口，没有回头；翔子站在黄线外，等编织袋消失才转身。"],"next":"c16-s05"},{"id":"c16-s05","chapterId":"c16","chapterNumber":16,"title":"群聊里的另一件事","location":"北桥站与房间","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["回到站点后，群聊安静了很久。小路忽然说自己二〇一八年夏天买的旧车还没登记，发票和整车合格证明留在老家，家人下周可以寄来。翔子只提醒他先拍清车型和凭证，别凭记忆就去窗口；等材料到，可以陪他去，但申请人得是小路自己。","三月末，翔子把银行卡余额核到一万二千三百九十元。宋嘉欣的路线复印页压在账本旁，他没有把她的离开算成支出，也没把她的选择记成自己失去了什么。小路的文件尚未寄到，四月三十日却已经写进日历。","她回家后的第一周，宋嘉欣照店长确认的八点到四点排班，放学后大多数日子自己接女儿。有一天店里临时多留她一小时，她提前给母亲打电话，母亲只帮忙接了这一次。宋嘉欣没有把这次帮助说成固定安排；这一周的接送暂时没有落空，也不等于以后每天都能一模一样。"],"next":"c17-s01"},{"id":"c17-s01","chapterId":"c17","chapterNumber":17,"title":"把原件送到手边","location":"北桥站","background":"station","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["四月三日，翔子收到三月结算五千三百五十元。上月底一万二千三百九十加上到账，再扣三千五百常态开支，原本还要从这个月余额中留出实际办事交通费；他没有把省掉的车租直接算成一笔新的收入。","小路寄来的材料在四月第一周到站，信封边角压皱，里面的购车发票和整车合格证明放在透明文件袋里。母亲翻了两个抽屉才找到原件。寄出前她还打电话问是否两张都要寄，小路让她按纸面标题分开放，型号看不清就别照记忆补，发票先别折，等收到后自己再核。","母亲答应后提醒他，收件了先给她回电话，别只发一句“到了”就算。小路把“原件待到”写进手机备忘录，没有提前把清单划成“已齐”。文件到手后，他把电动车也推到站里，请翔子一起看车架号、车型和票据上的字能不能对上。"],"next":"c17-s02"},{"id":"c17-s02","chapterId":"c17","chapterNumber":17,"title":"申请人是小路","location":"站点排班表旁","background":"station","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["小路说车是去年夏天买的，发票日期在十一月之前，型号列在登记目录内，他自己查过目录。翔子把发票车型、整车合格证明型号和目录名称逐项对过，三处写法一致，合格证明也在。即便如此，小路仍担心窗口还有别的材料。翔子把通知重新看了一遍：申请人身份证明、发票、整车合格证明、按窗口要求填的登记申请表，车辆还要带去查验。","翔子没有说“肯定没问题”，只把缺项列在纸上，让小路再核一次。小路问他忙的话是不是自己去就行，翔子说可以陪半天，但材料由申请人递交，自己只帮着看路和把带回来的纸收好。两个人约好一个工作日的上午。","翔子先把日期交给马力，问能不能把半天记作请假，下午再回来跑。马力说可以写进排班表，但这不是额外休息日，少接的单也不会自动补到别的班次；具体会少多少，要等五月三日结算。翔子在旁边签了名字，没有把请假划成“办手续免费”。","出发前，小路把材料按顺序放进文件夹。两人找了一辆能运车的短途货车，司机问电池能不能拆，小路取下电池抱在怀里，翔子和司机一起把车架推上后厢，用绑带固定车轮和车把。翔子拉了两下确认没松，文件夹和电池放在脚边。"],"next":"c17-s03"},{"id":"c17-s03","chapterId":"c17","chapterNumber":17,"title":"窗口核验","location":"电动车登记点","background":"office","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["登记点外排着几辆电动车。有人第一次来，有人拿维修单问车架号。窗口人员把申请表递给小路，让他按购买日期、车型和身份信息逐项填写。翔子站在旁边，没有替他回答。小路把自己的身份证明、购车发票和整车合格证明递进去，工作人员先核目录，再看车架号和车身标识。","前面一名车主翻了几遍文件夹仍找不到需要的证明。窗口人员只让他先把材料补齐，叫下一位过来。小路看着那个人把车推到一边，又低头数了一遍自己的文件；原件、身份证和车辆都在，他才把申请表递过去。","发票一角的折痕挡住购买日期，工作人员问车是什么时候买的。小路自己把原件展开，指出年份和月份，又把日期填进表格。工作人员对照目录和合格证明，确认符合首次登记条件，让他把车推进查验位置，检查车架和制动装置。","工作人员问发票上的购买人是不是小路本人。他把身份证递过去，说是自己买的；翔子没有替他说话。没有争吵，也没有人替他们开后门。需要补的表格就补，核对完成后再等叫号；小路自己把问题答完，也自己把车推到查验位置。","翔子想起自己十一月办的是已有登记车辆的所有权变更，车牌和登记信息原本就存在；小路这辆车是本人买下后第一次登记。两件事都要核对车和证件，却不是同一种手续。他没有把自己的过户经历当成小路一定能办成的保证。"],"next":"c17-s04"},{"id":"c17-s04","chapterId":"c17","chapterNumber":17,"title":"免费登记与五十元运费","location":"登记点门外","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["窗口确认材料齐全后，把登记凭证递给小路，并说明这项首次登记不收工本费。小路先看车主姓名，再逐位核对车架号和日期，确认申请栏里写的是自己，才收进透明文件袋。他又问还有没有其他窗口费用，工作人员说这次流程没有收费项目。","短途货车还停在门外。翔子和小路把车重新固定在后厢，电池仍由小路抱着。来回运车费五十元，翔子直接付给司机；小路想分一半，翔子说是自己愿意陪来的，不用争。小路在自己的办事记录上写“运车50，翔子已付”，不是等着以后报销。","回站路上，小路问翔子请假会不会影响结算。翔子说半天没上线，五月三日到账时可能少一点，现在还不知道具体少多少。登记本身没有收费，这五十是运车费，半天少跑订单的影响仍要等结算，不能把两件事混成一笔“窗口费”。"],"next":"c17-s05"},{"id":"c17-s05","chapterId":"c17","chapterNumber":17,"title":"复测通过","location":"鲁师傅修车铺","background":"shop","portrait":"lu","portraitLabel":"","speaker":"旁白","pages":["回到站点后，小路把新凭证拍照存进手机，也发回家。母亲提醒原件不要折，问那两个抽屉是不是总算没白翻；小路说放好了，把发票和凭证夹回透明袋。日期离四月三十日还不到三周，他把工牌背面的期限划掉，车主的登记已经有了实际凭证。","几天后，翔子收工带着何师傅那只旧刹车灯绕到鲁师傅的小铺。何师傅刚结束排定的半天时段，把当天做完的活记进本子。那只灯不是客人送修的工件，只是他们要补完的练习；之前只写到“弹片回位，待装车试灯”，还不能叫修好。","何师傅把灯装回自己的旧车，先检查接点和刹车开关，再捏住后刹推车过门口浅坎。红光没有断。他停下、松开，再捏两次，灯都亮着。翔子把“待装车试灯”划掉，改成“装车复测通过”。这次复测没有另算维修收入；登记完成，手工也有一项终于经过装车验证。"],"next":"c18-s01"},{"id":"c18-s01","chapterId":"c18","chapterNumber":18,"title":"期限前的凭证","location":"北桥站与街道","background":"station","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["二〇一九年四月三十日，翔子在站点群里看见小路发来登记凭证照片。第一张里车架号、车型和车主姓名被折痕挡住一角，小路又补发一张拍得清楚的。群里有人回了个拇指，马力只说“材料收好”。翔子看了两遍日期，确认小路在期限前办妥首次登记。","这天是四月最后一班。翔子早上翻开新账页：三月结算五千三百五十元已在四月三日到账；上月底一万二千三百九十，加上结算，再扣三千五百常态开支和陪小路登记的五十元交通费，账面一万四千一百九十。五月三日的四月结算还没来，当月订单不能先写成余额。","上午的单子多在站点附近。他按熟路线取餐、送到楼门，等餐时把车支稳，不再腾一只手刷手机。午饭时护腕内侧被汗浸潮，右手不麻，只是握久了发紧。他把这一点记在工作页边，没有因手还能转，就把晚上的每一笔订单预先算成必跑。"],"next":"c18-s02"},{"id":"c18-s02","chapterId":"c18","chapterNumber":18,"title":"最后一单看电量","location":"施工路口","background":"street","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["傍晚，平台推来一单距离偏远、时间很紧的订单。翔子停在路边，先看路线，再看车上的电量格：只剩一格。蓝线要穿过正在施工的路段，隔离栏挡去半个路口；绕行主路更长，交付时间也更难赶。","他松开电门，等仪表稳定下来，格数没有变。这块电池冬天换过，却没有任何续航保证。手腕在连续握把和刹车后又酸起来，护腕边缘磨硬；转腕时痛感不重，手指握把却慢了一拍。订单页没有告诉他施工路能不能过，也没写电池能不能撑到终点。","他可以接单再赌一回，也可以暂不接。平台没有替他选，站里也没人站在身后催。"],"choice":{"flag":"c18_risk_focus","prompt":"记录卡先圈哪项风险？","options":[{"value":"battery","label":"先圈剩一格电","note":"记录卡：这块电池冬天换过，续航没有保证。"},{"value":"construction","label":"先圈施工绕行","note":"记录卡：施工路段通行情况未知；绕行主路更长。"}]},"next":"c18-s03"},{"id":"c18-s03","chapterId":"c18","chapterNumber":18,"title":"四十元维修费","location":"站点外巷口","background":"night","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["翔子盯着地址十几秒，最后按下暂不接单。页面让他选理由，他点了“电量不足”，关掉接单状态，把手机收进外套。回站后，马力问为什么没接；翔子说只剩一格、路段要绕，手腕也开始疼。马力把未接订单和当前班次记清，提醒他五月到账时再看系统怎么结算。翔子没有说自己完全不后悔。","下线后走出站门，胶带哥在路边等着，车后刹车灯一过坑就灭，平地又亮。翔子先说如果只是接线松，维修工钱四十；要换零件会先告知另算。对方同意后，他才让车靠墙，先让骑手断电，再检查后灯。灯泡没裂，接线端子松了。","翔子压紧接点，把线束固定回车架，免得颠簸时再松。胶带哥把车推到路灯下，后轮压过细接缝，又连续捏两次刹车，红灯都亮。对方先拿出二十元，问没换零件为什么收这么多；翔子解释这算维修劳动，不是零件钱，如果觉得不值可以不收。","胶带哥看了看车灯，把另外二十递过来。翔子收下四十，回屋在账页上单列“副业收入40”，没有塞进订单结算。修好一盏灯不抵消拒单的未知结算影响，也不意味着以后每晚都有维修活。现金从一万四千一百九十增加四十，成为一万四千二百三十。"],"next":"c18-s04"},{"id":"c18-s04","chapterId":"c18","chapterNumber":18,"title":"不是开店承诺","location":"房间桌边","background":"room","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["电话里，许福兰说自己已经选好职校专业，报名材料交齐，后面按学校安排实习。翔子问她还想不想换，她说不换，自己看过课程，知道哪一部分喜欢、哪一部分不喜欢；实习单位尚未确定，正式通知下来她会再去问。","“那你后面要交的费用呢？”翔子问。许福兰说先按学校通知记着，不会因为看到新清单就先找哥哥要钱。母亲在旁边提醒她把凭证放进文件夹。翔子听见纸页翻动，觉得妹妹已经能把自己的事情说完整，不必把未来交给哥哥替她决定。这里没有新增一笔转账。","他把手机放下，翻出修理铺预算：工具、押金、第一批配件和周转金合计两万元，是他自己估的数，不是别人给他的开店承诺。账面可用的一万四千二百三十离那条线还差五千七百七十；房屋押金九百仍在高姨手里，不能拿来填表。","他把预算分成“已有”和“还要准备”两栏，把小扳手、螺丝刀和绝缘胶布逐样摆开。它们够处理几种常见接头，却不是一套能长期接活的工具；鲁师傅店里的检测表也不算在他名下。翔子在两万元旁补了“待询价”，没把一个整数写成已经算准的成本。","他把预算拍给鲁师傅问哪项最容易估错。鲁师傅回语音说铺面没定，租金报不出来；先列清要接什么活，等看中地方再算押金、水电和工具台，别先买用不上的东西。翔子听了两遍，只在纸边写“先找位置、问租金水电”，没有把这段语音当成报价或开店保证。","他又在纸背画一张小表，列“常见故障、所需工具、能否安全处理”：尾灯接点、电池外部卡扣、换胎写进能处理的一栏；电池壳里的电芯仍空着。账页上的副业收入四十元只是今晚一次，不能当成每月都能付铺租的流水。表哥的旧借款早已还完，他没有立刻再开口借钱，只把差额留在纸上。"],"next":"c18-s05"},{"id":"c18-s05","chapterId":"c18","chapterNumber":18,"title":"明天还要上班","location":"楼道与房间","background":"night","portrait":"xiang","portraitLabel":"","speaker":"旁白","pages":["他把“开店”留在计划栏，没写“明年一定”。车已经登记在自己名下，车头灯照着楼下路面；车票背面上，路线、开支和订单号挤在一起，最近又多了几行维修记录。","翔子把电动车推进楼道，电量表仍亮着一格。他关掉手机里的接单状态，没有再等提示把自己留下。窗外没有人喊他回站，屏幕也暗下去。","明天他仍要上班。今晚这一格电不必再用来证明还能多跑一单；修理铺也还只是计划，没有被写成结局。明天的排班仍是骑手的班次，不是铺面何时开门的承诺。"],"next":null}]};
